		["Light Glossy Metal"] = "Light Glossy Metal [Medium]",
		["Light Glossy Combo"] = "Combo Glossy [Heavy]",
	}

	function Config.findSky(name)
		for _, sky in ipairs(Config.Skyboxes) do
			if sky.Name == name then
				return sky
			end
		end
		for _, sky in ipairs(Config.ExtraSkies or {}) do
			if sky.Name == name then
				return sky
			end
		end
		return Config.Skyboxes[1]
	end

	function Config.findPreset(name)
		name = Config.PresetAliases[name] or name
		for _, preset in ipairs(Config.Presets) do
			if preset.Name == name or preset.Key == name then
				return preset
			end
		end
		-- Backwards compatibility: effect-only looks used by old share codes/API.
		for _, preset in ipairs(Config.ExtraPresets or {}) do
			if preset.Name == name or preset.Key == name then
				return preset
			end
		end
		return nil
	end

	return Config
end

-- ===== Module: Effects =====
__modules["Effects"] = function()
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Lighting = game:GetService("Lighting")
	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")
	local Players = game:GetService("Players")
	local Workspace = game:GetService("Workspace")

	local Config = __require("Config")

	local player = Players.LocalPlayer
	local playerGui = player:WaitForChild("PlayerGui")

	-- Executors do not always share `shared` between runs, so a previous execution
	-- can keep its RenderStepped loop alive and re-apply Headless/Korblox behind
	-- the new instance's back ("Headless off but still headless"). A global
	-- generation counter lets stale loops shut themselves down.
	local generation = 1
	pcall(function()
		generation = (tonumber(_G.__ShaderVelardGeneration) or 0) + 1
		_G.__ShaderVelardGeneration = generation
	end)
	local function isCurrentGeneration()
		local ok, value = pcall(function()
			return _G.__ShaderVelardGeneration
		end)
		return (not ok) or value == nil or value == generation
	end

	for _, partName in ipairs({
		"ShaderVelard_BananoFloor",
		"ShaderVelard_RTXFloor",
		"ShaderVelard_WindVFX",
		"ShaderVelard_DiscoLight",
	}) do
		local stale = Workspace:FindFirstChild(partName)
		if stale then
			stale:Destroy()
		end
	end
	-- Glossy overlays from a previous execution are welded clones named
	-- Preset_Overlay. Sweep them so an old run cannot leave a translucent box
	-- around the avatar.
	for _, descendant in ipairs(Workspace:GetDescendants()) do
		if descendant.Name == "Preset_Overlay" then
			descendant:Destroy()
		end
	end
	local staleSky = Lighting:FindFirstChild("ShaderVelard_Sky")
	if staleSky then
		staleSky:Destroy()
	end
	local existingTerrain = Workspace:FindFirstChildOfClass("Terrain")
	if existingTerrain then
		local staleClouds = existingTerrain:FindFirstChild("ShaderVelard_Clouds")
		if staleClouds then
			staleClouds:Destroy()
		end
	end
	local character = player.Character
	if character then
		local root = character:FindFirstChild("HumanoidRootPart")
		local staleAura = root and root:FindFirstChild("ShaderVelard_DiscoAura")
		if staleAura then
			staleAura:Destroy()
		end
	end

	local Effects = {}

	local function copy(value)
		if type(value) ~= "table" then
			return value
		end
		local out = {}
		for k, v in pairs(value) do
			out[k] = copy(v)
		end
		return out
	end

	local function merge(target, source)
		for k, v in pairs(source) do
			if type(v) == "table" and type(target[k]) == "table" then
				merge(target[k], v)
			else
				target[k] = copy(v)
			end
		end
		return target
	end

	local function safeSet(instance, property, value)
		local ok = pcall(function()
			instance[property] = value
		end)
		return ok
	end

	-- Attribute helpers: never let a restricted instance or a bad attribute name
	-- break the cosmetic apply path.
	local function setAttr(instance, name, value)
		pcall(function()
			instance:SetAttribute(name, value)
		end)
	end

	local function getAttr(instance, name)
		local ok, value = pcall(function()
			return instance:GetAttribute(name)
		end)
		if ok then
			return value
		end
		return nil
	end

	local function normalizeSkyTexture(value)
		value = tostring(value or "")
		value = string.gsub(value, "%s+", "")
		if value == "" then
			return nil
		end
		if string.match(value, "^%d+$") then
			return "rbxassetid://" .. value
		end
		if string.match(value, "^rbxassetid://%d+$") then
			return value
		end
		local id = string.match(value, "[%?&]id=(%d+)")
		if id then
			return "rbxassetid://" .. id
		end
		if string.match(value, "^rbxasset://") then
			return value
		end
		return nil
	end

	local POST_CLASSES = {
		{ key = "Atmosphere", class = "Atmosphere" },
		{ key = "Bloom", class = "BloomEffect" },
		{ key = "ColorCorrection", class = "ColorCorrectionEffect" },
		{ key = "DepthOfField", class = "DepthOfFieldEffect" },
		{ key = "SunRays", class = "SunRaysEffect" },
	}
	local posts = {}

	-- A previous execution can leave its post-processing instances behind. If one
	-- of those is picked up as the game's "original", resetAll() restores the
	-- previous run's Enabled=true ColorCorrection and the effect appears stuck.
	-- ShaderVelard-owned instances are always treated as disposable.
	for _, post in ipairs(POST_CLASSES) do
		local stale = Lighting:FindFirstChild("ShaderVelard_" .. post.key)
		if stale then
			stale:Destroy()
		end
	end
	-- Motion blur is a real BlurEffect owned by this script. A previous execution
	-- must not leave it enabled, otherwise the whole screen stays blurry.
	local staleMotionBlur = Lighting:FindFirstChild("ShaderVelard_MotionBlur")
	if staleMotionBlur then
		staleMotionBlur:Destroy()
	end

	local function postClassFor(key)
		for _, entry in ipairs(POST_CLASSES) do
			if entry.key == key then
				return entry.class
			end
		end
		return key
	end

	local function ensurePost(className)
		local entry = posts[className]
		if entry and entry.instance and entry.instance.Parent == Lighting then
			return entry.instance
		end

		local class = postClassFor(className)
		local instance = Lighting:FindFirstChildOfClass(class)
		local created = false
		if instance and string.sub(instance.Name, 1, 13) == "ShaderVelard_" then
			-- Never treat our own leftover as the game's original.
			instance:Destroy()
			instance = nil
		end
		if not instance then
			instance = Instance.new(class)
			instance.Name = "ShaderVelard_" .. className
			instance.Parent = Lighting
			created = true
		end

		entry = { instance = instance, created = created, props = {} }
		if not created then
			local defaults = Config.NeutralLook[className] or {}
			for key in pairs(defaults) do
				local ok, value = pcall(function()
					return instance[key]
				end)
				if ok then
					entry.props[key] = value
				end
			end
			local ok, enabled = pcall(function()
				return instance.Enabled
			end)
			if ok then
				entry.props.Enabled = enabled
			end
		end
		posts[className] = entry
		return instance
	end

	local lightingOriginal = {}
	for key in pairs(Config.NeutralLook.Lighting) do
		local ok, value = pcall(function()
			return Lighting[key]
		end)
		if ok then
			lightingOriginal[key] = value
		end
	end

	local terrain = Workspace.Terrain
	local TERRAIN_KEYS = { "WaterColor", "WaterReflectance", "WaterTransparency", "WaterWaveSize", "WaterWaveSpeed" }
	local terrainOriginal = {}
	for _, key in ipairs(TERRAIN_KEYS) do
		local ok, value = pcall(function()
			return terrain[key]
		end)
		if ok then
			terrainOriginal[key] = value
		end
	end

	local globalWindOriginal = Workspace.GlobalWind
	local initialFov = Workspace.CurrentCamera and Workspace.CurrentCamera.FieldOfView or 70

	local skyInstance = Lighting:FindFirstChildOfClass("Sky")
	local skyOriginal = nil
	local skyWasCreated = false
	if skyInstance then
		skyOriginal = {}
		for _, key in ipairs({
			"SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp",
			"StarCount", "CelestialBodiesShown", "SunAngularSize", "MoonAngularSize",
			"SunTextureId", "MoonTextureId",
		}) do
			local ok, value = pcall(function()
				return skyInstance[key]
			end)
			if ok then
				skyOriginal[key] = value
			end
		end
	end

	-- Celestial body defaults live in Effects._applyCelestials: Roblox's own
	-- round sun/moon are the fallback, so a skybox with a custom (often square)
	-- sun texture can never leak into the next sky.

	local cloudsOriginal = nil
	local cloudsWasCreated = false
	local existingClouds = terrain:FindFirstChildOfClass("Clouds")
	if existingClouds then
		cloudsOriginal = {
			Cover = existingClouds.Cover,
			Density = existingClouds.Density,
			Color = existingClouds.Color,
			Enabled = existingClouds.Enabled,
		}
	end

	local function readBaseLook()
		local look = copy(Config.NeutralLook)

		for key in pairs(look.Lighting) do
			local ok, value = pcall(function()
				return Lighting[key]
			end)
			if ok then
				look.Lighting[key] = value
			end
		end

		for _, post in ipairs(POST_CLASSES) do
			local instance = Lighting:FindFirstChildOfClass(post.class)
			if instance and look[post.key] then
				for key in pairs(look[post.key]) do
					local ok, value = pcall(function()
						return instance[key]
					end)
					if ok then
						look[post.key][key] = value
					end
				end
			end
		end

		return look
	end

	local initialBase = readBaseLook()

	local state = {
		base = copy(initialBase),
		presetName = "None",
		skyName = "Default",
		skyIndex = 1,
		-- True when the active sky comes from the six-face custom/preset path.
