			hideSun = false,
			rain = false,
			clouds = false,
			lightning = false,
			wind = false,
			disco = false,
			discoBloom = false,
			discoAura = false,
			skyAnimation = false,
			-- P2 Smart Atmosphere (non-premium Joevan toggle, MAIN pc 9082-9096).
			-- Default OFF so preset parity is unaffected.
			smartAtmosphere = false,
			bokeh = false,
			motionBlur = false,
			vhs = false,
			reShade = false,
			watermark = false,
			neon = false,
			evadeLighting = false,
			winterTerrain = false,
			windVFX = false,
			banano = false,
			rtx = false,
			angelAura = false,
			motionTrail = false,
			skyText = false,
			universalSnow = false,
			sparkles = false,
			rainbow = false,
			policeFlash = false,
			korblox = false,
			headless = false,
			unusual = false,
			spoof = false,
			accessoryHidden = false,
			freecam = false,
			antiAFK = false,
			rtxWrapObjects = true,
			rtxWrapTerrain = true,
			bananoWrapObjects = true,
			bananoWrapTerrain = true,
		},
		sliders = {
			brightness = math.clamp(initialBase.Lighting.Brightness, 0, 5),
			exposure = math.clamp(initialBase.Lighting.ExposureCompensation, -2, 2),
			bloom = math.clamp(initialBase.Bloom.Intensity, 0, 5),
			bloomSize = math.clamp(initialBase.Bloom.Size, 0, 60),
			bloomThreshold = math.clamp(initialBase.Bloom.Threshold, 0, 3),
			saturation = math.clamp(initialBase.ColorCorrection.Saturation, -1, 1),
