			outdoorR = math.floor(initialBase.Lighting.OutdoorAmbient.R * 255 + 0.5),
			outdoorG = math.floor(initialBase.Lighting.OutdoorAmbient.G * 255 + 0.5),
			outdoorB = math.floor(initialBase.Lighting.OutdoorAmbient.B * 255 + 0.5),
			fogHaze = math.clamp(initialBase.Atmosphere.Haze, 0, 10),
			fogGlare = math.clamp(initialBase.Atmosphere.Glare, 0, 5),
			fogDecay = math.floor(initialBase.Atmosphere.Decay.R * 255 + 0.5),
			sunRaysIntensity = math.clamp(initialBase.SunRays.Intensity, 0, 1),
			sunRaysSpread = math.clamp(initialBase.SunRays.Spread, 0, 1),
			vignette = 0.35,
