			discoIntensity = 4,
			motionBlurStrength = 0.45,
			reShadeIntensity = 0.45,
			vhsIntensity = 0.5,
			snowIntensity = 55,
			neonIntensity = 1,
			auraSize = 3,
			auraSpeed = 1,
			trailLifetime = 0.6,
			skyTextSize = 60,
			skyTextThickness = 2,
			skyTextHeight = 140,
