		},
		dropdowns = {
			glossyMode = "Plastic",
			sunTint = "Neutral",
			discoMode = "Rainbow Wave",
			lightningPalette = "White",
			auraColor = "Gold",
			trailColor = "Cyan",
			skyTextColor = "White",
			skyTextAnim = "None",
			globalShadows = "On",
			accessory = "All Accessories",
