		},
		skyTextString = "ShaderVelard",
		-- Preset-only flag (no dedicated UI control): CyberpunkRaytracedNeon uses
		-- Joevan's DiscoColorizeLamps to tint existing lamps instead of only
		-- adding the remake's own disco lights.
		discoColorizeLamps = false,
		liteMode = false,
	}

	local initialSliders = copy(state.sliders)
	local initialDropdowns = copy(state.dropdowns)

	-- Session locks. A locked toggle is forced on and can never be turned off
	-- again until the player rejoins (the state lives only in this client script).
	local lockedToggles = {}
	do
		local persisted = nil
		pcall(function()
			persisted = _G.__ShaderVelardSessionLocks
		end)
		if type(persisted) ~= "table" then
			pcall(function()
				persisted = shared.__ShaderVelardSessionLocks
			end)
		end
		if type(persisted) == "table" then
			for key, value in pairs(persisted) do
				if value == true then
					lockedToggles[key] = true
					state.toggles[key] = true
				end
			end
		end
	end

	Effects.state = state
	Effects.onChanged = nil
	Effects.onStatus = nil
	Effects.onNotify = nil
	Effects.onSkyChanged = nil

	function Effects.isToggleLocked(name)
		return lockedToggles[name] == true
	end

	-- Locks a feature on for the rest of the session. Used by the Headless warning:
	-- once the player agrees, the toggle can never be switched back off.
	function Effects.lockToggle(name)
		lockedToggles[name] = true
		state.toggles[name] = true
		pcall(function()
			local persisted = _G.__ShaderVelardSessionLocks
			if type(persisted) ~= "table" then
				persisted = {}
				_G.__ShaderVelardSessionLocks = persisted
			end
			persisted[name] = true
		end)
		pcall(function()
			local persisted = shared.__ShaderVelardSessionLocks
			if type(persisted) ~= "table" then
				persisted = {}
				shared.__ShaderVelardSessionLocks = persisted
			end
			persisted[name] = true
		end)
		return true
	end

	local function setStatus(message)
		if Effects.onStatus then
			Effects.onStatus(message)
		end
	end

	local function notifyChanged()
		if Effects.onChanged then
			Effects.onChanged()
		end
	end

	local function particleCap(rate)
		local ceiling = state.liteMode and 30 or 60
		return math.clamp(rate, 0, ceiling)
