	local function newFrame(parent, name, properties)
		local frame = Instance.new("Frame")
		frame.Name = name
		frame.BorderSizePixel = 0
		frame.BackgroundColor3 = Color3.new(0, 0, 0)
		for key, value in pairs(properties or {}) do
