	local function ensureSky()
		if skyInstance and skyInstance.Parent == Lighting then
			return skyInstance
		end
		local found = Lighting:FindFirstChildOfClass("Sky")
		if found then
			skyInstance = found
			return skyInstance
		end
		skyInstance = Instance.new("Sky")
		skyInstance.Name = "ShaderVelard_Sky"
		skyInstance.Parent = Lighting
		skyWasCreated = true
		return skyInstance
	end

	-- Writes a complete celestial state. Missing textures fall back to the game's
	-- original sun/moon (or Roblox's round defaults), which prevents a custom
	-- square sun texture from a previous skybox leaking into the new one.
	function Effects._applyCelestials(sky, data, fallbackSunSize)
		data = data or {}
		local sun = data.SunTextureId
		if type(sun) ~= "string" or sun == "" then
			sun = skyOriginal and skyOriginal.SunTextureId
			if type(sun) ~= "string" or sun == "" then
				sun = "rbxasset://sky/sun.jpg"
			end
		end
		local moon = data.MoonTextureId
		if type(moon) ~= "string" or moon == "" then
			moon = skyOriginal and skyOriginal.MoonTextureId
			if type(moon) ~= "string" or moon == "" then
				moon = "rbxasset://sky/moon.jpg"
			end
		end
		local meta = {
			SunTextureId = sun,
			MoonTextureId = moon,
			StarCount = data.StarCount or 3000,
			CelestialBodiesShown = data.CelestialBodiesShown ~= false,
			SunAngularSize = data.SunAngularSize or fallbackSunSize or 21,
			MoonAngularSize = data.MoonAngularSize or (skyOriginal and skyOriginal.MoonAngularSize) or 11,
		}
		safeSet(sky, "SunTextureId", meta.SunTextureId)
		safeSet(sky, "MoonTextureId", meta.MoonTextureId)
		safeSet(sky, "StarCount", meta.StarCount)
		safeSet(sky, "CelestialBodiesShown", meta.CelestialBodiesShown)
		safeSet(sky, "SunAngularSize", state.toggles.hideSun and 0 or meta.SunAngularSize)
		safeSet(sky, "MoonAngularSize", meta.MoonAngularSize)
		return meta
	end

	local function syncSky()
		if not skyInstance or not skyInstance.Parent then
			return
		end
		local originalSize = skyOriginal and skyOriginal.SunAngularSize or 21
		if state.skyName == "Default" and not skyWasCreated then
			skyInstance.SunAngularSize = state.toggles.hideSun and 0 or originalSize
			return
		end
		if state.skyIsCustom then
			Effects._applyCelestials(skyInstance, state.customSkyMeta, originalSize)
			return
		end
		local data = Config.findSky(state.skyName)
		-- A built-in sky always owns its complete sun/moon state. Re-writing it on
		-- every look update also clears stale textures from a previous skybox.
		Effects._applyCelestials(skyInstance, data, 21)
	end

	function Effects.applySky(name)
		local data = Config.findSky(name)
		if data.Name == "Default" then
			if skyInstance and skyInstance.Parent then
				if skyWasCreated then
					skyInstance:Destroy()
					skyInstance = nil
					skyWasCreated = false
				elseif skyOriginal then
					for key, value in pairs(skyOriginal) do
						safeSet(skyInstance, key, value)
					end
				end
			end
			state.skyName = "Default"
			state.skyIndex = 1
			state.skyIsCustom = false
			state.customSkyMeta = nil
			if Effects.onSkyChanged then
				Effects.onSkyChanged("Default")
			end
			return "Default"
		end

		local sky = ensureSky()
		safeSet(sky, "SkyboxBk", data.Bk)
		safeSet(sky, "SkyboxDn", data.Dn)
		safeSet(sky, "SkyboxFt", data.Ft)
		safeSet(sky, "SkyboxLf", data.Lf)
		safeSet(sky, "SkyboxRt", data.Rt)
		safeSet(sky, "SkyboxUp", data.Up)
		-- Every built-in sky writes a full celestial state. If the sky does not
		-- define a sun/moon texture we restore the round default instead of
		-- leaving the previous sky's custom texture in place.
		Effects._applyCelestials(sky, data, 21)

		state.skyName = data.Name
		state.skyIndex = 0
		state.skyIsCustom = false
		state.customSkyMeta = nil
		for index, entry in ipairs(Config.Skyboxes) do
			if entry.Name == data.Name then
				state.skyIndex = index
				break
			end
		end

		if Effects.onSkyChanged then
			Effects.onSkyChanged(data.Name)
		end
		return data.Name
	end

	function Effects.applyCustomSky(faces, label, meta)
		faces = faces or {}
		local normalized = {}
		for _, key in ipairs({ "Bk", "Dn", "Ft", "Lf", "Rt", "Up" }) do
			local value = normalizeSkyTexture(faces[key])
			if not value then
				setStatus("Custom skybox: invalid " .. key .. " texture ID")
				return nil, "Invalid " .. key .. " texture ID"
			end
			normalized[key] = value
		end

		local sky = ensureSky()
		for key, value in pairs(normalized) do
			safeSet(sky, "Skybox" .. key, value)
		end

		-- Custom/preset faces keep Joevan's 3000 / true fallbacks. The textures
		-- that were not supplied are still reset to the round default so they
		-- cannot bleed in from the skybox that was active before.
		meta = meta or {}
		state.customSkyMeta = Effects._applyCelestials(sky, meta, skyOriginal and skyOriginal.SunAngularSize or 21)

		state.customSky = copy(normalized)
		state.skyName = label or "Custom"
		state.skyIndex = 0
		state.skyIsCustom = true

		if Effects.onSkyChanged then
			Effects.onSkyChanged(state.skyName)
		end
		setStatus("Applied custom 6-face skybox")
		return state.skyName
	end

	function Effects.revertSkybox()
		local result = Effects.applySky("Default")
		setStatus("Restored the game's original skybox")
		return result
	end

	local function restoreTerrain()
		if terrain then
			for key, value in pairs(terrainOriginal) do
				safeSet(terrain, key, value)
			end
		end
		safeSet(Workspace, "GlobalWind", globalWindOriginal)
	end

	local function clearGlossy(keepCache)
		for part, props in pairs(glossySaved) do
			if props.overlay and props.overlay.Parent then
				props.overlay:Destroy()
			end
			if part and part.Parent then
				pcall(function()
					part.Material = props.Material
					part.Reflectance = props.Reflectance
					part.Transparency = props.Transparency
					if props.MaterialVariant ~= nil then
						part.MaterialVariant = props.MaterialVariant
					end
				end)
			end
		end
		glossySaved = {}
		if not keepCache then
			glossyCandidates = nil
			glossyCacheBuilt = false
		end
		if glossyConnection then
			glossyConnection:Disconnect()
			glossyConnection = nil
		end
	end

	local function glossyMaterial()
		local mode = state.dropdowns.glossyMode
		if mode == "Metal" then
			return Enum.Material.Metal
		elseif mode == "Marble" then
			return Enum.Material.Marble
		elseif mode == "Water" or mode == "Glass" then
			return Enum.Material.Glass
		elseif mode == "All" then
			return nil
		end
		return Enum.Material.SmoothPlastic
	end

	function Effects._glossyStrength()
		-- Joevan FUNCTION #437 (GlossyIntensity callback, pc 0-11):
		--   v = GlossyIntensity; if v <= 10 then v = v * 10 end
		--   strength = 1 - v / 100
		-- The strength is written to the glossy overlay's Transparency, not to the
		-- part's Reflectance (FUNCTION #395 restores Material/Reflectance/
		-- Transparency/MaterialVariant when the overlay is removed).
		local v = tonumber(state.sliders.glossyIntensity)
		if v == nil then
			return nil
		end
		if v <= 10 then
			v = v * 10
		end
		return math.clamp(1 - v / 100, 0, 1)
	end

	function Effects._glossyIntensityActive()
		return (Effects._glossyStrength() or 0) < 0.999
	end

	local function glossyReflectance()
		-- Joevan applies each preset's literal Reflectance. SSR/SSR detail must not
		-- inflate it, otherwise every preset with SSR ends up as a >=0.5 mirror.
		return math.clamp(state.sliders.glossyReflectance, 0, 1)
	end

	local function reflectionRadius()
		local radius = nil
		if state.toggles.rtx then
			radius = state.sliders.rtxRadius
		end
		if state.toggles.banano then
			if radius then
				radius = math.min(radius, state.sliders.bananoRadius)
			else
				radius = state.sliders.bananoRadius
			end
		end
		return radius
	end

	local function reflectionOffset()
		local offset = 0
		if state.toggles.rtx then
			offset = math.max(offset, state.sliders.rtxOffset)
		end
		if state.toggles.banano then
			offset = math.max(offset, state.sliders.bananoOffset)
		end
		return offset
	end

	Effects._reflectionRadius = reflectionRadius
	Effects._reflectionOffset = reflectionOffset

	function Effects._effectiveGlossyRadius()
		local radius = reflectionRadius()
		if (state.toggles.rtx and state.toggles.rtxWrapObjects)
			or (state.toggles.banano and state.toggles.bananoWrapObjects) then
			return nil
		end
		return radius
	end

	function Effects._glossyOverlayCount()
		local count = 0
		for _ in pairs(glossySaved) do
			count = count + 1
		end
		return count
	end

	function Effects._glossyOverlayFor(part)
		local props = glossySaved[part]
		return props and props.overlay or nil
	end

	function Effects._glossySavedFor(part)
		return glossySaved[part]
	end

	local function glossyPass()
		local material = glossyMaterial()
		local reflectance = glossyReflectance()
		if state.toggles.banano then
			reflectance = math.max(reflectance, 0.25 + state.sliders.bananoLevel * 0.1)
		end
		if state.toggles.rtx then
			reflectance = math.max(reflectance, 0.3 + state.sliders.rtxLevel * 0.1)
		end
		reflectance = math.clamp(reflectance + reflectionOffset() * 0.05, 0, 1)
		local camera = Workspace.CurrentCamera
		local origin = camera and camera.CFrame.Position or nil
		return material, reflectance, origin, reflectionRadius()
	end

	Effects._glossyPass = glossyPass

	-- Joevan #467 marks MeshPart/WedgePart/CornerWedgePart/UnionOperation and any
	-- non-Block Part as "complex geometry": Size grows by 0.02 and the overlay is
	-- lifted by 0.045 studs. Block parts grow by 0.06 with no lift.
	Effects._glossyOverlayImpl = {}
	function Effects._glossyOverlayImpl.isComplex(part)
		local complex = false
		pcall(function()
			complex = part:IsA("MeshPart")
				or part:IsA("WedgePart")
				or part:IsA("CornerWedgePart")
				or part:IsA("UnionOperation")
		end)
		if not complex then
			local ok, shape = pcall(function()
				return part.Shape
			end)
			if ok and shape ~= nil then
				complex = shape ~= Enum.PartType.Block
			end
		end
		return complex
	end

	function Effects._glossyOverlayImpl.create(part, material, reflectance)
		-- Joevan clones the source part, clears DataModelMesh children, and welds
		-- the clone to the original (FUNCTION #467 pc 0-242).
		local overlay = nil
		local okClone, clone = pcall(function()
			return part:Clone()
		end)
		if okClone and clone ~= nil and clone.ClassName ~= nil then
			overlay = clone
			pcall(function()
				for _, child in ipairs(overlay:GetChildren()) do
					if child:IsA("DataModelMesh") then
						child:Destroy()
					end
				end
			end)
		else
			overlay = Instance.new("Part")
		end

		overlay.Name = "Preset_Overlay"
		if material then
			pcall(function()
				overlay.Material = material
			end)
		end
		pcall(function()
			overlay.Transparency = 0.85
			overlay.Reflectance = reflectance
			overlay.Color = Color3.fromRGB(15, 15, 15)
			overlay.CanCollide = false
			overlay.CanTouch = false
			overlay.CanQuery = false
			overlay.CastShadow = false
			overlay.Massless = true
		end)
		pcall(function()
			if overlay:IsA("MeshPart") then
				overlay.TextureID = ""
			end
		end)

		local complex = Effects._glossyOverlayImpl.isComplex(part)
		local growth = complex and 0.02 or 0.06
		local size = part.Size
		pcall(function()
			overlay.Size = Vector3.new(
				math.max(size.X + growth, 0.1),
				math.max(size.Y + growth, 0.1),
				math.max(size.Z + growth, 0.1)
			)
		end)
		if complex then
			local lifted = pcall(function()
				overlay.CFrame = part.CFrame + Vector3.new(0, 0.045, 0)
			end)
			if not lifted then
				pcall(function()
					overlay.CFrame = part.CFrame
				end)
			end
		else
			pcall(function()
				overlay.CFrame = part.CFrame
			end)
		end

		local weld = Instance.new("WeldConstraint")
		pcall(function()
			weld.Part0 = part
			weld.Part1 = overlay
			weld.Parent = overlay
		end)
		pcall(function()
			overlay.Parent = part.Parent or Workspace
		end)
		return overlay
	end

	function Effects._glossyOverlayImpl.update(props, material, reflectance)
		local overlay = props.overlay
		if not overlay or not overlay.Parent then
			return false
		end
		local strength = Effects._glossyStrength() or 1
		pcall(function()
			if material then
				overlay.Material = material
			end
			overlay.Reflectance = reflectance
			overlay.Transparency = strength
		end)
		return true
	end

	function Effects._isCharacterPart(part)
		local node = part
		while node do
			if type(node) == "table" and type(node.IsA) == "function" then
				local hit = false
				pcall(function()
					hit = (node:IsA("Model") and node:FindFirstChildOfClass("Humanoid") ~= nil)
						or node:IsA("Accessory")
						or node:IsA("Accoutrement")
				end)
				if hit then
					return true
				end
			end
			node = node.Parent
		end
		return false
	end

	local function collectGlossyPart(part, material, reflectance, origin, radius)
		if glossySaved[part] then
			Effects._glossyOverlayImpl.update(glossySaved[part], material, reflectance)
			return
		end
		if not part:IsA("BasePart") or part:IsA("Terrain") then
			return
		end
		-- Joevan's glossy pass only wraps the static world. Cloning the player or
		-- another character created a translucent "box" around the avatar, so
		-- character parts (including accessories/hats) are never wrapped here.
		if Effects._isCharacterPart(part) then
			return
		end
		-- Joevan FUNCTION #466 only selects anchored BaseParts. Character limbs and
		-- accessory handles are unanchored (and can be caught mid-load, before the
		-- Humanoid/Accessory parent chain exists). Requiring an anchored part is the
		-- reliable guard that stops the translucent clone boxes on the avatar.
		if not part.Anchored then
			return
		end
		local transparency = tonumber(part.Transparency) or 0
		if transparency > 0.95 or string.sub(part.Name, 1, 13) == "ShaderVelard_" then
			return
		end
		if string.sub(part.Name, 1, 14) == "Preset_Overlay" then
			return
		end
		if radius and origin and (part.Position - origin).Magnitude > radius then
			return
		end
		local props = {
			Material = part.Material,
			Reflectance = part.Reflectance,
			Transparency = part.Transparency,
		}
		local okVariant, variant = pcall(function()
			return part.MaterialVariant
		end)
		if okVariant then
			props.MaterialVariant = variant
		end
		props.overlay = Effects._glossyOverlayImpl.create(part, material, reflectance)
		glossySaved[part] = props
		Effects._glossyOverlayImpl.update(props, material, reflectance)
	end

	local function buildGlossyCache(limit)
		if glossyCacheBuilt then
			return
		end
		glossyCandidates = glossyCandidates or {}
		local seen = {}
		for _, part in ipairs(glossyCandidates) do
			if part and part.Parent then
				seen[part] = true
			end
		end
		local count = 0
		for _, descendant in ipairs(Workspace:GetDescendants()) do
			if descendant:IsA("BasePart") and not descendant:IsA("Terrain") then
				if not seen[descendant] then
					seen[descendant] = true
					glossyCandidates[#glossyCandidates + 1] = descendant
				end
				count = count + 1
				if count >= limit then
					break
				end
			end
		end
		glossyCacheBuilt = true
	end

	local function applyGlossy()
		local active = state.toggles.wetFloor or state.toggles.ssr or state.toggles.banano or state.toggles.rtx
		if active and not Effects._glossyIntensityActive() then
			active = false
		end
		if not active then
			clearGlossy()
			restoreTerrain()
			return
		end

		-- A character can stream in after the cache was built (or an accessory can
		-- be added before its character model). Release any overlay that ended up
		-- on a character so no translucent box is left around the head or body.
		-- Parts that became unanchored (for example a prop picked up by a rig) are
		-- released for the same reason.
		for part, props in pairs(glossySaved) do
			if Effects._isCharacterPart(part) or not part.Anchored then
				if props.overlay and props.overlay.Parent then
					props.overlay:Destroy()
				end
				if part and part.Parent then
					pcall(function()
						part.Material = props.Material
						part.Reflectance = props.Reflectance
						part.Transparency = props.Transparency
						if props.MaterialVariant ~= nil then
							part.MaterialVariant = props.MaterialVariant
						end
					end)
				end
				glossySaved[part] = nil
			end
		end

		local material, reflectance, origin = glossyPass()
		-- "Wrap All Objects" reflects the RTX/Banano option: when enabled the
		-- reflection pass ignores the radius and wraps the entire workspace.
		local radius = Effects._effectiveGlossyRadius()
		local limit = state.liteMode and 300 or 1800
		-- Cache the workspace part list. Slider changes (reflectance, SSR detail,
		-- thickness, radius, offset) then only touch known parts instead of walking
		-- every descendant again.
		buildGlossyCache(limit)
		for _, part in ipairs(glossyCandidates) do
			if part and part.Parent then
				collectGlossyPart(part, material, reflectance, origin, radius)
			end
		end

		local ssrOn = state.toggles.ssr == true
		local rtxTerrain = state.toggles.rtx == true and state.toggles.rtxWrapTerrain ~= false
		local bananoTerrain = state.toggles.banano == true and state.toggles.bananoWrapTerrain ~= false
		local terrainEnabled = ssrOn or rtxTerrain or bananoTerrain
		if terrainEnabled and terrain then
			local offset = reflectionOffset()
			local detail = ssrOn and state.sliders.ssrDetail or 0
			local opacity = ssrOn and state.sliders.ssrOpacity or 0
			local thickness = math.clamp(state.sliders.ssrThickness or 0.5, 0, 1)
			-- SSR's three controls each write a distinct terrain property:
			-- detail -> reflectance, opacity -> transparency, thickness -> waves.
			local levelBoost = 0
			if state.toggles.rtx then levelBoost = levelBoost + state.sliders.rtxLevel * 0.02 end
			if state.toggles.banano then levelBoost = levelBoost + state.sliders.bananoLevel * 0.02 end
			safeSet(terrain, "WaterReflectance", math.clamp(0.45 + detail * 0.45 + offset * 0.02 + levelBoost, 0, 0.95))
			safeSet(terrain, "WaterTransparency", math.clamp(0.4 - opacity * 0.3, 0.02, 0.45))
			safeSet(terrain, "WaterWaveSize", math.clamp(0.05 + thickness * 0.35, 0.02, 0.5))
			safeSet(terrain, "WaterWaveSpeed", 1 + thickness * 3)
		else
			restoreTerrain()
		end

		if not glossyConnection then
			glossyConnection = Workspace.DescendantAdded:Connect(function(instance)
				if state.toggles.wetFloor or state.toggles.ssr
					or state.toggles.banano or state.toggles.rtx then
					task.defer(function()
						if instance.Parent and (state.toggles.wetFloor or state.toggles.ssr
							or state.toggles.banano or state.toggles.rtx) then
							if glossyCandidates and instance:IsA("BasePart") and not instance:IsA("Terrain") then
								glossyCandidates[#glossyCandidates + 1] = instance
							end
							local freshMaterial, freshReflectance, freshOrigin, freshRadius = glossyPass()
							collectGlossyPart(instance, freshMaterial, freshReflectance, freshOrigin, freshRadius)
						end
					end)
				end
			end)
		end
	end

	local function refreshGlossy()
		clearGlossy(true)
		applyGlossy()
	end

	-- Joevan's Texture Detail (MAIN pc 3737 -> FUNCTION #314, setTextureDetail)
	-- walks workspace descendants and calls applyTex(instance, value)
	-- (FUNCTION #313). applyTex only changes two things:
	--   value  = GraphicStates.TextureDetail (0..100)
	--   alpha  = 1 - value / 100
	--   Texture/Decal.Transparency = original + (1 - original) * alpha
	-- BasePart Material is only touched for the "wet" look (value >= 50 keeps
	-- SmoothPlastic); the remake's glossy pass already owns wet materials, so the
	-- decal/texture transparency is the part that is missing here.
	local function textureDetailValue()
		return math.clamp(tonumber(state.sliders.textureDetail) or 0.5, 0, 1) * 100
	end

	-- isWet in Joevan #313 is the wet/glossy world state. The remake treats an
	-- active reflection pass as wet. The wet branch owns only the base part's
	-- Material; the glossy pass now owns a separate Preset_Overlay part, so the
	-- two never fight over the same property.
	function Effects._applyTextureWetMaterial(instance, value)
		if not instance:IsA("BasePart") or instance:IsA("Terrain") then
			return
		end
		local saved = Effects._textureMaterials[instance]
		local wet = state.toggles.wetFloor or state.toggles.ssr
			or state.toggles.banano or state.toggles.rtx
		if not wet then
			if saved then
				pcall(function()
					instance.Material = saved.Material
					instance.Reflectance = saved.Reflectance
				end)
				Effects._textureMaterials[instance] = nil
			end
			return
		end
		if string.sub(instance.Name, 1, 13) == "ShaderVelard_"
			or string.sub(instance.Name, 1, 14) == "Preset_Overlay" then
			return
		end
		local parent = instance.Parent
		if parent then
			local isHumanoid = false
			pcall(function()
				isHumanoid = parent:FindFirstChild("Humanoid") ~= nil
			end)
			if isHumanoid then
				return
			end
		end
		if not saved then
			saved = {
				Material = instance.Material,
				Reflectance = instance.Reflectance,
			}
			Effects._textureMaterials[instance] = saved
		end
		if value >= 50 then
			safeSet(instance, "Material", Enum.Material.SmoothPlastic)
		else
			safeSet(instance, "Material", saved.Material)
		end
	end

	local function applyTextureDetailTo(instance, value)
		if instance:IsA("Texture") or instance:IsA("Decal") then
			local saved = textureDetailSaved[instance]
			if not saved then
				saved = { Transparency = instance.Transparency }
				textureDetailSaved[instance] = saved
			end
			local alpha = 1 - value / 100
			safeSet(instance, "Transparency", saved.Transparency + (1 - saved.Transparency) * alpha)
			return
		end
		Effects._applyTextureWetMaterial(instance, value)
	end

	function Effects._applyTextureDetail()
		local value = textureDetailValue()
		for _, descendant in ipairs(Workspace:GetDescendants()) do
			applyTextureDetailTo(descendant, value)
		end
		if not textureDetailConnection then
			textureDetailConnection = Workspace.DescendantAdded:Connect(function(instance)
				if instance:IsA("Texture") or instance:IsA("Decal") then
					task.defer(function()
						if instance.Parent then
							applyTextureDetailTo(instance, textureDetailValue())
						end
					end)
				end
			end)
		end
		return value
	end

	function Effects._clearTextureDetail()
		for instance, saved in pairs(textureDetailSaved) do
			if instance and instance.Parent then
				safeSet(instance, "Transparency", saved.Transparency)
			end
		end
		for instance, saved in pairs(Effects._textureMaterials) do
			if instance and instance.Parent then
				pcall(function()
					instance.Material = saved.Material
					instance.Reflectance = saved.Reflectance
				end)
			end
		end
		textureDetailSaved = {}
		Effects._textureMaterials = {}
		if textureDetailConnection then
			textureDetailConnection:Disconnect()
			textureDetailConnection = nil
		end
	end

	function Effects._textureDetailSavedCount()
		local count = 0
		for _ in pairs(textureDetailSaved) do
			count = count + 1
		end
		return count
	end

	function Effects._textureMaterialSavedCount()
		local count = 0
		for _ in pairs(Effects._textureMaterials) do
			count = count + 1
		end
		return count
	end

	local function syncReflectionFloors()
		applyGlossy()
	end

	local function clearNeon()
		for _, highlight in pairs(neonHighlights) do
			if highlight and highlight.Parent then
				highlight:Destroy()
			end
		end
		neonHighlights = {}
		if neonConnection then
			neonConnection:Disconnect()
			neonConnection = nil
		end
	end

	local function refreshNeon()
		if not state.toggles.neon then
			clearNeon()
			return
		end
		local maxScan = state.liteMode and 600 or nil
		local scanned = 0
		for _, descendant in ipairs(Workspace:GetDescendants()) do
			if descendant:IsA("Model") and descendant:FindFirstChildOfClass("Humanoid") then
				if not neonHighlights[descendant] or not neonHighlights[descendant].Parent then
					local highlight = Instance.new("Highlight")
					highlight.Name = "ShaderVelard_Neon"
					highlight.FillTransparency = 1
					highlight.OutlineColor = Color3.fromHSV((clock * 0.18) % 1, 0.9, 1)
					highlight.OutlineTransparency = math.clamp(0.3 - state.sliders.neonIntensity * 0.25, 0, 0.8)
					highlight.DepthMode = Enum.HighlightDepthMode.Occluded
					highlight.Parent = descendant
					neonHighlights[descendant] = highlight
				end
			end
			if maxScan then
				scanned = scanned + 1
				if scanned >= maxScan then
					break
				end
			end
		end
		if not neonConnection then
			neonConnection = Workspace.DescendantAdded:Connect(function(instance)
				if state.toggles.neon and not state.liteMode
					and instance:IsA("Model") and instance:FindFirstChildOfClass("Humanoid") then
					task.defer(refreshNeon)
				end
			end)
		end
	end

	local function syncWindVFX()
		if not state.toggles.windVFX then
			if windVFXPart then
				windVFXPart:Destroy()
				windVFXPart = nil
				windVFXEmitter = nil
			end
			return
		end
		if windVFXPart and windVFXPart.Parent and windVFXEmitter and windVFXEmitter.Parent then
			return
		end
		windVFXPart = Instance.new("Part")
		windVFXPart.Name = "ShaderVelard_WindVFX"
		windVFXPart.Anchored = true
		windVFXPart.CanCollide = false
		windVFXPart.CanTouch = false
		windVFXPart.CanQuery = false
		windVFXPart.Size = Vector3.new(1, 1, 1)
		windVFXPart.Transparency = 1
		windVFXPart.Parent = Workspace

		windVFXEmitter = Instance.new("ParticleEmitter")
		windVFXEmitter.Name = "WindParticles"
		windVFXEmitter.Texture = "rbxasset://textures/particles/smoke_main.dds"
		windVFXEmitter.Color = ColorSequence.new(Color3.fromRGB(225, 245, 255))
		windVFXEmitter.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.08),
			NumberSequenceKeypoint.new(1, 0.35),
		})
		windVFXEmitter.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.8),
			NumberSequenceKeypoint.new(0.2, 0.4),
			NumberSequenceKeypoint.new(1, 1),
		})
		windVFXEmitter.Lifetime = NumberRange.new(0.8, 1.8)
		windVFXEmitter.Speed = NumberRange.new(8, 18)
		windVFXEmitter.SpreadAngle = Vector2.new(35, 35)
		windVFXEmitter.Rate = 24
		windVFXEmitter.LightEmission = 0
		windVFXEmitter.Rotation = NumberRange.new(0, 360)
		windVFXEmitter.Parent = windVFXPart
	end

	local function updateMotion()
		-- Never draw the radial starburst container; it reads as a lens/god-ray
		-- artifact rather than motion blur.
		motionContainer.Visible = false
		if not state.toggles.motionBlur and Effects._motionBlur then
			Effects._motionBlur.Enabled = false
			Effects._motionBlur.Size = 0
		end
	end

	local function localTimeString()
		local ok, text = pcall(function()
			return DateTime.now():FormatLocalTime("HH:mm:ss", "en-us")
		end)
		if ok and type(text) == "string" and text ~= "" then
			return text
		end
		local fallbackOk, fallbackText = pcall(function()
			return os.date("%H:%M:%S")
		end)
		if fallbackOk and type(fallbackText) == "string" and fallbackText ~= "" then
			return fallbackText
		end
		return "LIVE"
	end

	local function updateVhs()
		vhsContainer.Visible = state.toggles.vhs
		if state.toggles.vhs then
			vhsTime.Text = localTimeString()
		end
	end

	local function updateReShade()
		reShadeContainer.Visible = state.toggles.reShade
		if not state.toggles.reShade then
			return
		end
		local intensity = math.clamp(state.sliders.reShadeIntensity, 0, 1)
		reShadeCool.BackgroundTransparency = 1 - intensity * 0.12
		reShadeWarm.BackgroundTransparency = 1 - intensity * 0.07
		for _, line in ipairs(reShadeGrain) do
			line.BackgroundTransparency = 1 - intensity * 0.1
		end
	end

	local function updateSnow()
		snowContainer.Visible = state.toggles.winterTerrain
	end

	local function updateWatermark()
		watermarkLabel.Visible = state.toggles.watermark
	end

	local function clearCelHighlights()
		for _, highlight in pairs(celHighlights) do
			if highlight and highlight.Parent then
				highlight:Destroy()
			end
		end
		celHighlights = {}
		if celConnection then
			celConnection:Disconnect()
			celConnection = nil
		end
	end

	local function refreshCelHighlights()
		if not state.toggles.celShading then
			clearCelHighlights()
			return
		end
		local maxScan = state.liteMode and 600 or nil
		local scanned = 0
		for _, descendant in ipairs(Workspace:GetDescendants()) do
			if descendant:IsA("Model") and descendant:FindFirstChildOfClass("Humanoid") then
				if not celHighlights[descendant] or not celHighlights[descendant].Parent then
					local highlight = Instance.new("Highlight")
					highlight.Name = "ShaderVelard_Cel"
					highlight.FillTransparency = 1
					highlight.OutlineColor = Color3.fromRGB(10, 10, 12)
					highlight.OutlineTransparency = 0.15
					highlight.DepthMode = Enum.HighlightDepthMode.Occluded
					highlight.Parent = descendant
					celHighlights[descendant] = highlight
				end
			end
			if maxScan then
				scanned = scanned + 1
				if scanned >= maxScan then
					break
				end
			end
		end
		if not celConnection then
			celConnection = Workspace.DescendantAdded:Connect(function(instance)
				if state.toggles.celShading and not state.liteMode
					and instance:IsA("Model") and instance:FindFirstChildOfClass("Humanoid") then
					task.defer(refreshCelHighlights)
				end
			end)
		end
	end

	local function getClouds()
		local clouds = terrain:FindFirstChildOfClass("Clouds")
		if clouds then
			return clouds
		end
		local ok, instance = pcall(Instance.new, "Clouds")
		if not ok or not instance then
			return nil
		end
		clouds = instance
		clouds.Name = "ShaderVelard_Clouds"
		clouds.Parent = terrain
		cloudsWasCreated = true
		return clouds
	end

	local function clearClouds()
		local clouds = terrain:FindFirstChildOfClass("Clouds")
		if not clouds then
			return
		end
		if cloudsWasCreated then
			clouds:Destroy()
			cloudsWasCreated = false
		elseif cloudsOriginal then
			safeSet(clouds, "Cover", cloudsOriginal.Cover)
			safeSet(clouds, "Density", cloudsOriginal.Density)
			safeSet(clouds, "Color", cloudsOriginal.Color)
			safeSet(clouds, "Enabled", cloudsOriginal.Enabled)
		end
	end

	local function syncClouds()
		if not state.toggles.clouds then
			clearClouds()
			return
		end
		local clouds = getClouds()
		if not clouds then
			return
		end
		safeSet(clouds, "Enabled", true)
		safeSet(clouds, "Cover", math.clamp(state.sliders.cloudCover, 0, 1))
		safeSet(clouds, "Density", math.clamp(state.sliders.cloudDensity or 0.55, 0, 1))
		safeSet(clouds, "Color", Color3.fromRGB(255, 255, 255))
	end

	function Effects._restoreDiscoLamps()
		for light, props in pairs(Effects._discoLampSaved) do
			if light and light.Parent then
				pcall(function()
					light.Color = props.Color
					light.Brightness = props.Brightness
				end)
			end
		end
		Effects._discoLampSaved = {}
	end

	function Effects._colorizeDiscoLamps(intensity, mode)
		if not state.discoColorizeLamps or not state.toggles.disco then
			Effects._restoreDiscoLamps()
			return
		end
		for _, descendant in ipairs(Workspace:GetDescendants()) do
			local isLamp = descendant:IsA("PointLight")
				or descendant:IsA("SpotLight") or descendant:IsA("SurfaceLight")
			if isLamp and string.find(descendant.Name, "ShaderVelard_", 1, true) == nil then
				if not Effects._discoLampSaved[descendant] then
					Effects._discoLampSaved[descendant] = {
						Color = descendant.Color,
						Brightness = descendant.Brightness,
					}
				end
				local hue
				if mode == "Warm Pulse" then
					hue = 0.06 + math.sin(clock * 2) * 0.04
				elseif mode == "Cool Pulse" then
					hue = 0.55 + math.sin(clock * 2) * 0.05
				elseif mode == "Strobe" then
					hue = (math.floor(clock * 6) % 2 == 0) and 0 or 0.66
				elseif mode == "Neon Cyberpunk" then
					hue = (math.floor(clock * 3) % 2 == 0) and 0.5 or 0.85
				else
					hue = (clock * 0.18 * state.sliders.discoSpeed) % 1
				end
				pcall(function()
					descendant.Color = Color3.fromHSV((hue % 1 + 1) % 1, 0.85, 1)
					descendant.Brightness = math.max(1, intensity * (0.8 + math.sin(clock * 3) * 0.25))
				end)
			end
		end
	end

	local function clearDisco()
		if discoPart then
			discoPart:Destroy()
			discoPart = nil
		end
		discoLights = {}
		Effects._restoreDiscoLamps()
		if discoAuraLight then
			discoAuraLight:Destroy()
			discoAuraLight = nil
		end
	end

	local function ensureDisco()
		if discoPart and discoPart.Parent then
			return
		end
		discoPart = Instance.new("Part")
		discoPart.Name = "ShaderVelard_DiscoLight"
		discoPart.Anchored = true
		discoPart.CanCollide = false
		discoPart.CanTouch = false
		discoPart.CanQuery = false
		discoPart.Size = Vector3.new(1, 1, 1)
		discoPart.Transparency = 1
		discoPart.Parent = Workspace
		discoLights = {}
		for index = 1, 3 do
			local light = Instance.new("PointLight")
			light.Name = "DiscoLight" .. index
			light.Brightness = 4
			light.Range = 34
			light.Shadows = false
			light.Parent = discoPart
			discoLights[index] = light
		end
	end

	local function updateVignette()
		local strength = state.toggles.vignette and state.sliders.vignette or 0
		if strength <= 0.01 then
			vignetteContainer.Visible = false
			return
		end
		vignetteContainer.Visible = true
		local edgeTransparency = 1 - math.clamp(strength, 0, 1) * 0.58
		for _, data in pairs(vignetteEdges) do
			data.gradient.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, edgeTransparency),
				NumberSequenceKeypoint.new(1, 1),
			})
		end
	end

	local function updateLetterbox()
		local visible = state.toggles.letterbox
		if visible then
			letterboxTop.Visible = true
			letterboxBottom.Visible = true
		end
		local goal = visible and UDim2.new(1, 0, 0.085, 0) or UDim2.new(1, 0, 0, 0)
		local info = TweenInfo.new(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		TweenService:Create(letterboxTop, info, { Size = goal }):Play()
		local bottomGoal = visible and UDim2.new(1, 0, 0.085, 0) or UDim2.new(1, 0, 0, 0)
		TweenService:Create(letterboxBottom, info, { Size = bottomGoal }):Play()
		if not visible then
			task.delay(0.4, function()
				if not state.toggles.letterbox then
					letterboxTop.Visible = false
					letterboxBottom.Visible = false
				end
			end)
		end
	end

	local function updateChromatic()
		chromaticContainer.Visible = state.toggles.chromatic
		if not state.toggles.chromatic then
			return
		end
		local strength = state.sliders.chromaticStrength
		local thickness = math.clamp(2 + strength * 6, 2, 18)
		chromaticLeft.Size = UDim2.new(0, thickness, 1, 0)
		chromaticRight.Size = UDim2.new(0, thickness, 1, 0)
		chromaticTop.Size = UDim2.new(1, 0, 0, math.clamp(1 + strength * 2, 1, 8))
	end

	local function updateRain()
		rainContainer.Visible = state.toggles.rain
		if not state.toggles.rain then
			return
		end
		local intensity = math.clamp(state.sliders.rainIntensity / 100, 0.1, 1)
		for _, drop in ipairs(rainStreaks) do
			drop.frame.BackgroundTransparency = 1 - intensity * drop.alpha
			drop.frame.Visible = true
		end
	end

	local function updateScanlines()
		scanlineContainer.Visible = state.toggles.nightVision
	end

	local function updateFlare()
		flareContainer.Visible = state.toggles.lensFlare
	end

	local function writeLook(look)
		for key, value in pairs(look.Lighting) do
			safeSet(Lighting, key, value)
		end

		local atmosphere = ensurePost("Atmosphere")
		for key, value in pairs(look.Atmosphere) do
			safeSet(atmosphere, key, value)
		end

		local bloom = ensurePost("Bloom")
		for key, value in pairs(look.Bloom) do
			safeSet(bloom, key, value)
		end

		local correction = ensurePost("ColorCorrection")
		safeSet(correction, "Enabled", true)
		for key, value in pairs(look.ColorCorrection) do
			safeSet(correction, key, value)
		end

		local dof = ensurePost("DepthOfField")
		for key, value in pairs(look.DepthOfField) do
			safeSet(dof, key, value)
		end

		local sunRays = ensurePost("SunRays")
		for key, value in pairs(look.SunRays) do
			safeSet(sunRays, key, value)
		end

		if state.toggles.hideSun then
			safeSet(sunRays, "Intensity", 0)
		end

		local camera = Workspace.CurrentCamera
		if camera then
			safeSet(camera, "FieldOfView", state.sliders.fov)
		end

		syncSky()
	end

	local fx = {}

	fx.nightVision = function(look)
		look.ColorCorrection.TintColor = Color3.fromRGB(130, 255, 150)
		look.ColorCorrection.Saturation = -0.35
		look.ColorCorrection.Brightness = look.ColorCorrection.Brightness + 0.06
		look.ColorCorrection.Contrast = look.ColorCorrection.Contrast + 0.08
		look.Bloom.Intensity = look.Bloom.Intensity + 0.5
	end

	fx.monochrome = function(look)
		look.ColorCorrection.Saturation = -1
		look.ColorCorrection.TintColor = Color3.fromRGB(245, 245, 250)
		look.ColorCorrection.Contrast = look.ColorCorrection.Contrast + 0.1
	end

	fx.celShading = function(look)
		-- Joevan setCelShading (FUNCTION #199) only builds Highlight outlines around
		-- character rigs (FUNCTION #195); it never rewrites Lighting/post values.
		-- The remake keeps the outline pass in refreshCelHighlights(), so this must
		-- not contribute any Look delta.
	end

	fx.greenScreen = function(look)
		look.ColorCorrection.TintColor = Color3.fromRGB(120, 255, 120)
		look.ColorCorrection.Saturation = 1
		look.ColorCorrection.Contrast = look.ColorCorrection.Contrast + 0.12
		look.Lighting.FogColor = Color3.fromRGB(20, 210, 40)
		look.Lighting.FogStart = 0
		look.Lighting.FogEnd = 340
		look.Atmosphere.Density = math.max(look.Atmosphere.Density, 0.55)
		look.Atmosphere.Color = Color3.fromRGB(40, 220, 70)
	end

	fx.fakeSSAO = function(look)
		-- Joevan setFakeSSAO (FUNCTION #239 pc 30-73) writes a fixed "ambient
		-- occlusion" lighting state, not a delta. Values are literal from the
		-- disassembly.
		look.Lighting.Brightness = 1.7
		look.Lighting.EnvironmentDiffuseScale = 0.6
		look.Lighting.EnvironmentSpecularScale = 0.5
		look.Lighting.ShadowSoftness = 1.0
		look.Lighting.ClockTime = 14.3
		look.Lighting.GeographicLatitude = 32
		look.Lighting.ExposureCompensation = 0
		look.Lighting.Ambient = Color3.fromRGB(77, 75, 75)
		look.Lighting.OutdoorAmbient = Color3.fromRGB(64, 70, 74)
	end

	fx.bokeh = function(look)
		-- Joevan setBokehIntensity (FUNCTION #193) and the dynamic-DOF pass
		-- (FUNCTION #192): FarIntensity = bokehIntensity, NearIntensity =
		-- bokehIntensity * 0.5, InFocusRadius = 15, FocusDistance = camera to
		-- HumanoidRootPart distance. With no character the preset's FocusDistance
		-- is kept.
		local intensity = math.clamp(state.sliders.bokehIntensity, 0, 1)
		look.DepthOfField.FarIntensity = intensity
		look.DepthOfField.NearIntensity = intensity * 0.5
		look.DepthOfField.InFocusRadius = 15
		local character = player.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		local camera = Workspace.CurrentCamera
		if root and camera then
			local ok, distance = pcall(function()
				return (camera.CFrame.Position - root.Position).Magnitude
			end)
			if ok and type(distance) == "number" then
				look.DepthOfField.FocusDistance = distance
			end
		end
	end

	fx.vhs = function(look)
		look.ColorCorrection.Saturation = look.ColorCorrection.Saturation - 0.08
		look.ColorCorrection.Contrast = look.ColorCorrection.Contrast + 0.05
	end

	fx.reShade = function(look)
		-- Joevan setReShadeOverlay (FUNCTION #211) is a GUI-only filmic gradient
		-- overlay (Frame + UIGradient, BackgroundTransparency 0.85). It does not
		-- touch ColorCorrection or Bloom. updateReShade() already draws the overlay.
	end

	fx.disco = function(look)
		if state.toggles.discoBloom then
			look.Bloom.Intensity = look.Bloom.Intensity + state.sliders.discoIntensity * 0.08
			look.ColorCorrection.Saturation = look.ColorCorrection.Saturation + 0.06
		end
	end

	fx.evadeLighting = function(look)
		for key, value in pairs(lightingOriginal) do
			look.Lighting[key] = value
		end
		look.Atmosphere.Density = 0.15
		look.Atmosphere.Haze = 1
		look.Atmosphere.Glare = 0
		look.Bloom.Intensity = 0
		look.SunRays.Intensity = 0
		look.DepthOfField.FarIntensity = 0
		look.DepthOfField.NearIntensity = 0
		look.ColorCorrection.Brightness = 0
		look.ColorCorrection.Contrast = 0
		look.ColorCorrection.Saturation = 0
	end

	local sunTints = {
		Neutral = { top = Color3.fromRGB(0, 0, 0), bottom = Color3.fromRGB(0, 0, 0) },
		Warm = { top = Color3.fromRGB(255, 205, 160), bottom = Color3.fromRGB(95, 62, 38) },
		Cool = { top = Color3.fromRGB(165, 205, 255), bottom = Color3.fromRGB(40, 62, 92) },
		Red = { top = Color3.fromRGB(255, 96, 84), bottom = Color3.fromRGB(62, 12, 12) },
		Gold = { top = Color3.fromRGB(255, 218, 132), bottom = Color3.fromRGB(96, 66, 22) },
		Blue = { top = Color3.fromRGB(120, 180, 255), bottom = Color3.fromRGB(12, 32, 82) },
	}

	function Effects.recompute()
		local look = copy(state.base)
		-- Standalone GlobalShadows override exposed as a toggle.
		if state.dropdowns.globalShadows == "Off" then
			look.Lighting.GlobalShadows = false
		elseif state.dropdowns.globalShadows == "On" then
			look.Lighting.GlobalShadows = true
		end
		local baseSaturation = look.ColorCorrection.Saturation
		local baseContrast = look.ColorCorrection.Contrast
		for _, name in ipairs({
			"nightVision", "monochrome", "celShading", "greenScreen", "fakeSSAO",
			"bokeh", "vhs", "reShade", "disco", "evadeLighting",
		}) do
			if state.toggles[name] and fx[name] then
				fx[name](look)
			end
		end

		if state.sliders.saturation ~= nil then
			local fxDelta = look.ColorCorrection.Saturation - baseSaturation
			look.ColorCorrection.Saturation = math.clamp(state.sliders.saturation + fxDelta, -1, 1)
		end
		if state.sliders.contrast ~= nil then
			local fxDelta = look.ColorCorrection.Contrast - baseContrast
			look.ColorCorrection.Contrast = math.clamp(state.sliders.contrast + fxDelta, -1, 1)
		end

		local tint = sunTints[state.dropdowns.sunTint]
		-- "Neutral" means "leave the preset's ColorShift alone". Applying the black
		-- Neutral table here used to erase every preset's ColorShift_Top/Bottom
		-- (Joevan writes those literal values from the preset).
		if tint and state.dropdowns.sunTint ~= "Neutral" then
			look.Lighting.ColorShift_Top = tint.top
			look.Lighting.ColorShift_Bottom = tint.bottom
		end

		-- P2 Smart Atmosphere: Joevan's non-premium generator fallback
		-- (FUNCTION #1209 pc 509-568) with GraphicStates defaults atmosDensity
		-- 0.28 (pc 6857) and atmosHaze 0.8 (pc 6862). Off = preset values untouched.
		if state.toggles.smartAtmosphere then
			local density = tonumber(state.atmosDensity) or 0.28
			local haze = tonumber(state.atmosHaze) or 0.8
			look.Atmosphere.Density = math.clamp(density, 0, 1)
			look.Atmosphere.Offset = 0.2
			look.Atmosphere.Color = Color3.fromRGB(190, 215, 245)
			look.Atmosphere.Decay = Color3.fromRGB(110, 130, 160)
			look.Atmosphere.Glare = 0.25
			look.Atmosphere.Haze = math.clamp(haze, 0, 10)
		end

		writeLook(look)
	end

	local function advanceSky()
		local count = #Config.Skyboxes
		state.skyIndex = (state.skyIndex % count) + 1
		local data = Config.Skyboxes[state.skyIndex]
		Effects.applySky(data.Name)
	end

	Effects._tickSkyAnimation = function(deltaTime)
		if not state.toggles.skyAnimation then
			skyTimer = 0
			return false
		end
		skyTimer = skyTimer + deltaTime
		if skyTimer >= math.max(state.sliders.skySpeed or 7, 0.05) then
			skyTimer = 0
			advanceSky()
			return true
		end
		return false
	end


	local featureColors = {
		White = Color3.fromRGB(255, 255, 255),
		Gold = Color3.fromRGB(255, 214, 130),
		Cyan = Color3.fromRGB(120, 240, 255),
		Pink = Color3.fromRGB(255, 150, 220),
		Purple = Color3.fromRGB(190, 150, 255),
		Red = Color3.fromRGB(255, 92, 92),
		Green = Color3.fromRGB(140, 255, 170),
		Blue = Color3.fromRGB(120, 170, 255),
	}

	local function featureColor(name)
		return featureColors[name] or featureColors.White
	end

	local function getRootPart()
		local char = player.Character
		return char and char:FindFirstChild("HumanoidRootPart") or nil
	end

	local function clearAura()
		if auraEmitter then
			auraEmitter:Destroy()
			auraEmitter = nil
		end
		if auraAttachment then
			auraAttachment:Destroy()
			auraAttachment = nil
		end
		if auraLight then
			auraLight:Destroy()
			auraLight = nil
		end
	end

	local function updateAuraStyle()
		if not auraEmitter then
			return
		end
		local color = featureColor(state.dropdowns.auraColor)
		auraEmitter.Color = ColorSequence.new(color)
		auraEmitter.Rate = particleCap(10 + state.sliders.auraSize * 5)
		local baseSize = 0.35 + state.sliders.auraSize * 0.16
		auraEmitter.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, baseSize),
			NumberSequenceKeypoint.new(1, 0),
		})
		local speed = state.sliders.auraSpeed
		auraEmitter.Speed = NumberRange.new(0.8 + speed, 2.2 + speed * 1.6)
		if auraLight then
			auraLight.Color = color
			auraLight.Brightness = 0.6 + state.sliders.auraSize * 0.12
		end
	end

	local function ensureAura()
		local root = getRootPart()
		if not root then
			return
		end
		if auraEmitter and auraEmitter.Parent and auraAttachment and auraAttachment.Parent == root then
			updateAuraStyle()
			return
		end
		clearAura()
		local attachment = Instance.new("Attachment")
		attachment.Name = "ShaderVelard_AuraAttach"
		attachment.Parent = root

		local emitter = Instance.new("ParticleEmitter")
		emitter.Name = "ShaderVelard_AngelAura"
		emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		emitter.LightEmission = 1
		emitter.LightInfluence = 0
		emitter.Lifetime = NumberRange.new(1.1, 1.9)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Acceleration = Vector3.new(0, 5, 0)
		emitter.Rotation = NumberRange.new(0, 360)
		emitter.RotSpeed = NumberRange.new(-40, 40)
		emitter.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.1),
			NumberSequenceKeypoint.new(1, 1),
		})
		emitter.Parent = attachment

		auraAttachment = attachment
		auraEmitter = emitter

		local light = Instance.new("PointLight")
		light.Name = "ShaderVelard_AuraLight"
		light.Range = 13
		light.Shadows = false
		light.Parent = root
		auraLight = light

		updateAuraStyle()
	end

	local function clearTrail()
		if trailInstance then
			trailInstance:Destroy()
			trailInstance = nil
		end
		if trailAttachTop then
			trailAttachTop:Destroy()
			trailAttachTop = nil
		end
		if trailAttachBottom then
			trailAttachBottom:Destroy()
			trailAttachBottom = nil
		end
	end

	local function updateTrailStyle()
		if not trailInstance then
			return
		end
		local color = featureColor(state.dropdowns.trailColor)
		trailInstance.Color = ColorSequence.new(color, color)
		trailInstance.Lifetime = math.clamp(state.sliders.trailLifetime, 0.1, 3)
	end

	local function ensureTrail()
		local root = getRootPart()
		if not root then
			return
		end
		if trailInstance and trailInstance.Parent and trailAttachTop and trailAttachTop.Parent == root then
			updateTrailStyle()
			return
		end
		clearTrail()
		local top = Instance.new("Attachment")
		top.Name = "ShaderVelard_TrailTop"
		top.Position = Vector3.new(0, 1.4, 0)
		top.Parent = root
		local bottom = Instance.new("Attachment")
		bottom.Name = "ShaderVelard_TrailBottom"
		bottom.Position = Vector3.new(0, -1.4, 0)
		bottom.Parent = root
		local trail = Instance.new("Trail")
		trail.Name = "ShaderVelard_MotionTrail"
		trail.Attachment0 = top
		trail.Attachment1 = bottom
		trail.FaceCamera = true
		trail.LightEmission = 1
		trail.LightInfluence = 0
		trail.MaxLength = 12
		trail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.1),
			NumberSequenceKeypoint.new(1, 1),
		})
		trail.Parent = root
		trailInstance = trail
		trailAttachTop = top
		trailAttachBottom = bottom
		updateTrailStyle()
	end

	-- ===== Character suite (client-side only) ===== (engine closure)
	Effects._character = (function()
	local UserInputService = game:GetService("UserInputService")
	local unusualAttachment = nil
	local unusualEmitter = nil
	local unusualLight = nil
	local accessoryOriginal = setmetatable({}, { __mode = "k" })
	local spoofOriginal = {}
	local emoteTracks = {}
	local freecamSaved = nil
	local freecamCFrame = nil
	local freecamConnections = nil
	local freecamKeys = {}
	local antiAfkConnection = nil
	local antiAfkTimer = 0

	-- ===== Character suite (client-side only) =====
	-- Accessories, unusual effect, local appearance spoof and local emotes all
	-- operate on the player's own character. Nothing here sends a remote.

	local function getCharacter()
		local character = player.Character
		if character and character ~= false then
			return character
		end
		return nil
	end

	function Effects.getAccessoryNames()
		local names = {}
		local seen = {}
		local character = getCharacter()
		if character then
			for _, child in ipairs(character:GetChildren()) do
				if child:IsA("Accessory") then
					local name = tostring(child.Name or "Accessory")
					if not seen[name] then
						seen[name] = true
						names[#names + 1] = name
					end
				end
			end
		end
		table.sort(names)
		return names
	end

	function Effects.refreshAccessories()
		local character = getCharacter()
		if not character then
			return false
		end
		local target = state.dropdowns.accessory or "All Accessories"
		local hide = state.toggles.accessoryHidden == true
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("Accessory") then
				local shouldHide = hide and (target == "All Accessories" or target == child.Name)
				for _, descendant in ipairs(child:GetDescendants()) do
					if descendant:IsA("BasePart") then
						if accessoryOriginal[descendant] == nil then
							local ok, original = pcall(function()
								return descendant.LocalTransparencyModifier
							end)
							accessoryOriginal[descendant] = ok and (original or 0) or 0
						end
						pcall(function()
							descendant.LocalTransparencyModifier = shouldHide and 1 or accessoryOriginal[descendant]
						end)
					end
				end
			end
		end
		return true
	end

	local function clearAccessories()
		for part, original in pairs(accessoryOriginal) do
			if part and part.Parent then
				pcall(function()
					part.LocalTransparencyModifier = original
				end)
			end
		end
		accessoryOriginal = setmetatable({}, { __mode = "k" })
	end

	local unusualStyles = {
		Sparkle = { texture = "rbxasset://textures/particles/sparkles_main.dds", emission = 1 },
		Flame = { texture = "rbxasset://textures/particles/fire_main.dds", emission = 0.9 },
		Orb = { texture = "rbxasset://textures/particles/smoke_main.dds", emission = 0.4 },
		Storm = { texture = "rbxasset://textures/particles/explosion01_implosion_main.dds", emission = 1 },
	}

	local function updateUnusualStyle()
		if not unusualEmitter then
			return
		end
		local style = unusualStyles[state.dropdowns.unusualStyle] or unusualStyles.Sparkle
		local color = featureColor(state.dropdowns.auraColor)
		unusualEmitter.Texture = style.texture
		unusualEmitter.LightEmission = style.emission
		unusualEmitter.Color = ColorSequence.new(color)
		unusualEmitter.Rate = particleCap(6 + state.sliders.unusualSize * 7)
		local baseSize = 0.25 + state.sliders.unusualSize * 0.12
		unusualEmitter.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, baseSize),
			NumberSequenceKeypoint.new(0.6, baseSize * 1.4),
			NumberSequenceKeypoint.new(1, 0),
		})
		if unusualLight then
			unusualLight.Color = color
			unusualLight.Brightness = 0.5 + state.sliders.unusualSize * 0.1
			unusualLight.Range = 8 + state.sliders.unusualSize * 1.2
		end
	end

	local function clearUnusual()
		if unusualEmitter then
			unusualEmitter:Destroy()
			unusualEmitter = nil
		end
		if unusualAttachment then
			unusualAttachment:Destroy()
			unusualAttachment = nil
		end
		if unusualLight then
			unusualLight:Destroy()
			unusualLight = nil
		end
	end

	local function ensureUnusual()
		local root = getRootPart()
		if not root then
			return false
		end
		if unusualEmitter and unusualAttachment and unusualAttachment.Parent == root then
			updateUnusualStyle()
			return true
		end
		clearUnusual()
		local attachment = Instance.new("Attachment")
		attachment.Name = "ShaderVelard_UnusualAttach"
		attachment.Position = Vector3.new(0, 2.5, 0)
		attachment.Parent = root
		local emitter = Instance.new("ParticleEmitter")
		emitter.Name = "ShaderVelard_Unusual"
		emitter.LightInfluence = 0
		emitter.Lifetime = NumberRange.new(0.7, 1.4)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Speed = NumberRange.new(1, 3)
		emitter.Rotation = NumberRange.new(0, 360)
		emitter.RotSpeed = NumberRange.new(-60, 60)
		emitter.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.1),
			NumberSequenceKeypoint.new(1, 1),
		})
		emitter.Parent = attachment
		local light = Instance.new("PointLight")
		light.Name = "ShaderVelard_UnusualLight"
		light.Shadows = false
		light.Parent = root
		unusualAttachment = attachment
		unusualEmitter = emitter
		unusualLight = light
		updateUnusualStyle()
		return true
	end

	local spoofColors = {
		Neon = Color3.fromRGB(70, 245, 235),
		Shadow = Color3.fromRGB(24, 24, 30),
		Gold = Color3.fromRGB(255, 205, 90),
		Ice = Color3.fromRGB(165, 220, 255),
		Rose = Color3.fromRGB(255, 140, 190),
		Random = nil,
	}

	local function spoofColor()
		if state.dropdowns.spoofStyle == "Random" then
			return Color3.fromHSV(math.random(), 0.55, 1)
		end
		return spoofColors[state.dropdowns.spoofStyle] or spoofColors.Neon
	end

	local function applySpoof()
		local character = getCharacter()
		if not character then
			return false
		end
		local color = spoofColor()
		for _, child in ipairs(character:GetChildren()) do
			if child:IsA("BasePart") then
				if spoofOriginal[child] == nil then
					spoofOriginal[child] = child.Color
				end
				pcall(function()
					child.Color = color
					child.Material = Enum.Material.SmoothPlastic
				end)
			end
		end
		local bodyColors = character:FindFirstChildOfClass("BodyColors")
		if bodyColors then
			for _, property in ipairs({
				"HeadColor3", "TorsoColor3", "LeftArmColor3", "RightArmColor3",
				"LeftLegColor3", "RightLegColor3",
			}) do
				pcall(function()
					bodyColors[property] = color
				end)
			end
		end
		return true
	end

	local function clearSpoof()
		for part, original in pairs(spoofOriginal) do
			if part and part.Parent then
				pcall(function()
					part.Color = original
				end)
			end
		end
		spoofOriginal = {}
	end

	local EMOTE_IDS = {
		Wave = 507770239,
		Dance = 507771019,
		Point = 507770453,
		Laugh = 507770818,
		Cheer = 507770677,
		Salute = 507770565,
	}

	function Effects.getEmoteNames()
		local names = {}
		for name in pairs(EMOTE_IDS) do
			names[#names + 1] = name
		end
		table.sort(names)
		return names
	end

	-- Emotes are played locally on the player's own Animator. Roblox does not give
	-- a client script permission to replicate an emote to other players' Humanoids,
	-- so this is intentionally local-only (no remote is created).
	function Effects.playEmote(name)
		local character = getCharacter()
		if not character then
			return false, "Character not loaded"
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return false, "No Humanoid found"
		end
		local animator = humanoid:FindFirstChildOfClass("Animator")
		if not animator then
			local ok, created = pcall(function()
				local value = Instance.new("Animator")
				value.Parent = humanoid
				return value
			end)
			if not ok then
				return false, "Animator unavailable"
			end
			animator = created
		end
		local id = EMOTE_IDS[name] or EMOTE_IDS.Wave
		local animation = Instance.new("Animation")
		animation.Name = "ShaderVelard_Emote"
		animation.AnimationId = "rbxassetid://" .. tostring(id)
		local ok, track = pcall(function()
			return animator:LoadAnimation(animation)
		end)
		if not ok or not track then
			return false, "Could not load emote"
		end
		local played = pcall(function()
			track.Looped = false
			track:Play()
		end)
		if not played then
			return false, "Could not play emote"
		end
		emoteTracks[#emoteTracks + 1] = track
		task.delay(8, function()
			pcall(function()
				if track.IsPlaying then
					track:Stop()
				end
			end)
			pcall(function()
				animation:Destroy()
			end)
		end)
		return true
	end

	-- ===== Freecam =====
	local FREECAM_KEYMAP = {
		[Enum.KeyCode.W] = "forward",
		[Enum.KeyCode.S] = "back",
		[Enum.KeyCode.A] = "left",
		[Enum.KeyCode.D] = "right",
		[Enum.KeyCode.E] = "up",
		[Enum.KeyCode.Q] = "down",
		[Enum.KeyCode.LeftShift] = "fast",
	}

	local function disconnectFreecamInput()
		if freecamConnections then
			for _, connection in ipairs(freecamConnections) do
				pcall(function()
					connection:Disconnect()
				end)
			end
		end
		freecamConnections = nil
	end

	local function stopFreecam()
		disconnectFreecamInput()
		freecamKeys = {}
		local camera = Workspace.CurrentCamera
		if freecamSaved then
			if camera then
				pcall(function()
					camera.CameraType = freecamSaved.CameraType
					camera.CameraSubject = freecamSaved.CameraSubject
				end)
			end
			freecamSaved = nil
		end
		freecamCFrame = nil
	end

	local function startFreecam()
		local camera = Workspace.CurrentCamera
		if not camera then
			return false
		end
		if freecamSaved then
			return true
		end
		freecamSaved = {
			CameraType = camera.CameraType,
			CameraSubject = camera.CameraSubject,
		}
		freecamCFrame = camera.CFrame
		freecamKeys = {}
		pcall(function()
			camera.CameraType = Enum.CameraType.Scriptable
			camera.CameraSubject = nil
		end)

		freecamConnections = {
			UserInputService.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.Keyboard then
					local action = FREECAM_KEYMAP[input.KeyCode]
					if action then
						freecamKeys[action] = true
					end
				end
			end),
			UserInputService.InputEnded:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.Keyboard then
					local action = FREECAM_KEYMAP[input.KeyCode]
					if action then
						freecamKeys[action] = false
					end
				end
			end),
			UserInputService.InputChanged:Connect(function(input)
				if not freecamCFrame then
					return
				end
				if input.UserInputType == Enum.UserInputType.MouseMovement then
					local ok, delta = pcall(function()
						return input.Delta
					end)
					if ok and delta then
						local yaw = -delta.X * 0.0024
						local pitch = -delta.Y * 0.0024
						pcall(function()
							freecamCFrame = freecamCFrame * CFrame.Angles(0, yaw, 0) * CFrame.Angles(pitch, 0, 0)
						end)
					end
				end
			end),
		}
		return true
	end

	local function updateFreecam(deltaTime)
		local camera = Workspace.CurrentCamera
		if not camera or not freecamCFrame then
			return
		end
		local move = Vector3.new(
			(freecamKeys.right and 1 or 0) - (freecamKeys.left and 1 or 0),
			(freecamKeys.up and 1 or 0) - (freecamKeys.down and 1 or 0),
			(freecamKeys.back and 1 or 0) - (freecamKeys.forward and 1 or 0)
		)
		if move.Magnitude > 0 then
			local speed = (freecamKeys.fast and 105 or 32) * deltaTime
			pcall(function()
				freecamCFrame = freecamCFrame + freecamCFrame:VectorToWorldSpace(move.Unit * speed)
			end)
		end
		pcall(function()
			camera.CameraType = Enum.CameraType.Scriptable
			camera.CFrame = freecamCFrame
		end)
	end

	function Effects.setFreecam(value)
		value = value == true
		state.toggles.freecam = value
		if value then
			if not startFreecam() then
				state.toggles.freecam = false
				setStatus("Freecam unavailable: no camera")
				notifyChanged()
				return false
			end
		else
			stopFreecam()
		end
		notifyChanged()
		setStatus(value and "Freecam enabled (WASD / QE / Shift, move the mouse to look)" or "Freecam disabled")
		return value
	end

	function Effects.isFreecam()
		return state.toggles.freecam == true
	end

	-- ===== Anti-AFK =====
	local function applyAntiAfk(value)
		if value then
			if antiAfkConnection then
				return
			end
			antiAfkTimer = 0
			antiAfkConnection = RunService.Heartbeat:Connect(function(deltaTime)
				if not state.toggles.antiAFK then
					return
				end
				antiAfkTimer = antiAfkTimer + deltaTime
				if antiAfkTimer < 60 then
					return
				end
				antiAfkTimer = 0
				pcall(function()
					local virtualUser = game:GetService("VirtualUser")
					virtualUser:CaptureController()
					virtualUser:ClickButton1(Vector2.new(0, 0))
					virtualUser:ClickButton2(Vector2.new(0, 0))
				end)
			end)
		elseif antiAfkConnection then
			antiAfkConnection:Disconnect()
			antiAfkConnection = nil
			antiAfkTimer = 0
		end
	end

	function Effects.setAntiAFK(value)
		value = value == true
		state.toggles.antiAFK = value
		applyAntiAfk(value)
		notifyChanged()
		setStatus(value and "Anti-AFK enabled (60s heartbeat)" or "Anti-AFK disabled")
		return value
	end


	local function tickUnusual()
		local root = getRootPart()
		if root and (not unusualAttachment or unusualAttachment.Parent ~= root) then
			ensureUnusual()
		end
		if unusualEmitter and state.dropdowns.auraColor == "Rainbow" then
			local color = Color3.fromHSV((clock * 0.18) % 1, 0.75, 1)
			unusualEmitter.Color = ColorSequence.new(color)
			if unusualLight then
				unusualLight.Color = color
			end
		end
	end

	return {
		getAccessoryNames = Effects.getAccessoryNames,
		refreshAccessories = Effects.refreshAccessories,
		ensureUnusual = ensureUnusual,
		clearUnusual = clearUnusual,
		updateUnusualStyle = updateUnusualStyle,
		tickUnusual = tickUnusual,
		applySpoof = applySpoof,
		clearSpoof = clearSpoof,
		playEmote = Effects.playEmote,
		getEmoteNames = Effects.getEmoteNames,
		startFreecam = startFreecam,
		stopFreecam = stopFreecam,
		updateFreecam = updateFreecam,
		applyAntiAfk = applyAntiAfk,
		clearAccessories = clearAccessories,
		resetEmotes = function()
			for _, track in ipairs(emoteTracks) do
				pcall(function()
					if track.IsPlaying then
						track:Stop()
					end
				end)
			end
			emoteTracks = {}
		end,
	}
	end)()

