	local function updateUniversalParticles()
		if not state.toggles.universalSnow and not state.toggles.sparkles then
			if universalSnowPart then
				universalSnowPart:Destroy()
				universalSnowPart = nil
				universalSnowEmitter = nil
				sparkleEmitter = nil
			end
			return
		end
		if not universalSnowPart or not universalSnowPart.Parent then
			ensureUniversalPart()
		end
		if universalSnowEmitter then
			universalSnowEmitter.Enabled = state.toggles.universalSnow == true
			universalSnowEmitter.Rate = particleCap(15 + state.sliders.snowRate * 0.5)
		end
		if sparkleEmitter then
			sparkleEmitter.Enabled = state.toggles.sparkles == true
			sparkleEmitter.Rate = particleCap(8 + state.sliders.sparkleRate * 0.5)
		end
	end

	-- ===== Character cosmetics (Korblox right leg / Headless) =====
	-- Restored verbatim from commit e0f3f3d "Add Korblox and Headless cosmetic
	-- features", the version that was confirmed working. Do not swap the R15
	-- Part+SpecialMesh weld for anything else: that is the implementation that
	-- renders correctly in the games this bundle is used in.
	local KORBLOX_MESH_ID = 101851696
	local KORBLOX_TEXTURE_ID = 101851254
	local HEADLESS_HEAD_MESH = "rbxassetid://15093053680"

	local function collectCosmeticRigs()
		local rigs = {}
		local function add(model)
			if model and typeof(model) == "Instance" and model:IsA("Model") then
				table.insert(rigs, model)
			end
		end

		local currentCharacter = player.Character
		if currentCharacter
			and (currentCharacter:FindFirstChild("Right Leg")
				or currentCharacter:FindFirstChild("RightLeg")
				or currentCharacter:FindFirstChild("RightUpperLeg")) then
			add(currentCharacter)
		end

		local rigsFolder = Workspace:FindFirstChild("Rigs")
		if rigsFolder and rigsFolder:FindFirstChild(player.Name) then
			add(rigsFolder[player.Name])
		end

		local playerCache = Workspace:FindFirstChild("PlayerCache")
		if playerCache and playerCache:FindFirstChild(player.Name) then
			local entry = playerCache[player.Name]
			local r6 = entry and entry:FindFirstChild("R6")
			if r6 then
				add(r6)
			end
		end

		for _, object in ipairs(playerGui:GetDescendants()) do
			if object:IsA("Model") and object.Name == "VisualRigClassic" and object:FindFirstChild("Right Leg") then
				table.insert(rigs, object)
			end
		end

		return rigs
	end

	local function logCosmeticRigs(tag)
		local names = {}
		for _, rig in ipairs(collectCosmeticRigs()) do
			local ok, fullName = pcall(function()
				return rig:GetFullName()
			end)
			table.insert(names, ok and fullName or rig.Name)
		end
		print("[ShaderVelard] " .. tag .. " rigs (" .. #names .. "): " .. table.concat(names, ", "))
	end

	local function matchRightLegStyle(rig)
		local rightLeg = rig:FindFirstChild("Right Leg") or rig:FindFirstChild("RightLeg")
		local leftLeg = rig:FindFirstChild("Left Leg") or rig:FindFirstChild("LeftLeg")
		if rightLeg and leftLeg and rightLeg:IsA("BasePart") and leftLeg:IsA("BasePart") then
			rightLeg.Color = leftLeg.Color
			rightLeg.Material = leftLeg.Material
			rightLeg.Reflectance = 0
		end
	end

	local function rigUsesR15(rig)
		local humanoid = rig:FindFirstChildOfClass("Humanoid")
		if humanoid then
			return humanoid.RigType == Enum.HumanoidRigType.R15
		end
		return rig:FindFirstChild("RightUpperLeg") ~= nil
	end

	local function applyKorbloxR15(rig)
		local upperLeg = rig:FindFirstChild("RightUpperLeg")
		if not upperLeg or not upperLeg:IsA("BasePart") then
			return false
		end
		local lowerLeg = rig:FindFirstChild("RightLowerLeg")
		local foot = rig:FindFirstChild("RightFoot")

		-- R15 legs are MeshParts, so the R6 CharacterMesh cannot be used.
		-- Hide the real right leg and weld a Korblox mesh in its place.
		for _, part in ipairs({ upperLeg, lowerLeg, foot }) do
			if part and part:IsA("BasePart") then
				if cosmeticCache.korblox[part] == nil then
					cosmeticCache.korblox[part] = part.Transparency
					setAttr(part, "ShaderVelardKorbloxTransparency", part.Transparency)
				end
				part.Transparency = 1
			end
		end

		if rig:FindFirstChild("ShaderVelard_KorbloxLeg") then
			return true
		end

		local upperLen = upperLeg.Size.Y
		local lowerLen = lowerLeg and lowerLeg.Size.Y or upperLen
		local footLen = foot and foot.Size.Y or math.max(upperLen * 0.5, 0.2)
		local totalLen = upperLen + lowerLen + footLen
		local offsetY = -(lowerLen + footLen) / 2

		local legPart = Instance.new("Part")
		legPart.Name = "ShaderVelard_KorbloxLeg"
		legPart.Size = Vector3.new(upperLeg.Size.X, totalLen, upperLeg.Size.Z)
		legPart.CFrame = upperLeg.CFrame * CFrame.new(0, offsetY, 0)
		legPart.Anchored = false
		legPart.CanCollide = false
		legPart.CanQuery = false
		legPart.CanTouch = false
		legPart.CastShadow = false
		legPart.Massless = true
		legPart.Color = Color3.fromRGB(64, 64, 64)
		legPart.Parent = rig

		local mesh = Instance.new("SpecialMesh")
		mesh.Name = "KorbloxMesh"
		mesh.MeshType = Enum.MeshType.FileMesh
		mesh.MeshId = "rbxassetid://" .. KORBLOX_MESH_ID
		mesh.TextureId = "rbxassetid://" .. KORBLOX_TEXTURE_ID
		mesh.Scale = Vector3.new(1, totalLen / 2, 1)
		mesh.Parent = legPart

		local weld = Instance.new("Weld")
		weld.Name = "KorbloxWeld"
		weld.Part0 = upperLeg
		weld.Part1 = legPart
		weld.C0 = CFrame.new(0, offsetY, 0)
		weld.Parent = legPart

		return true
	end

	local function applyKorbloxLeg(rig)
		if rigUsesR15(rig) then
			return applyKorbloxR15(rig)
		end

		matchRightLegStyle(rig)
		for _, child in ipairs(rig:GetChildren()) do
			if child:IsA("CharacterMesh") and child.BodyPart == Enum.BodyPart.RightLeg then
				local meshId = tostring(child.MeshId)
				if meshId == ("rbxassetid://" .. KORBLOX_MESH_ID)
					or tonumber(meshId) == KORBLOX_MESH_ID
					or string.find(child.Name:lower(), "korblox", 1, true) then
					return true
				end
			end
		end
		local mesh = Instance.new("CharacterMesh")
		mesh.Name = "ShaderVelard_KorbloxRightLeg"
		mesh.BodyPart = Enum.BodyPart.RightLeg
		mesh.MeshId = KORBLOX_MESH_ID
		mesh.OverlayTextureId = KORBLOX_TEXTURE_ID
		mesh.Parent = rig
		return true
	end

	local function clearKorbloxLeg(rig)
		local welded = rig:FindFirstChild("ShaderVelard_KorbloxLeg")
		if welded then
			welded:Destroy()
		end
		for _, name in ipairs({ "RightUpperLeg", "RightLowerLeg", "RightFoot" }) do
			local part = rig:FindFirstChild(name)
			if part and part:IsA("BasePart") then
				local original = cosmeticCache.korblox[part]
				if original == nil then
					local stored = getAttr(part, "ShaderVelardKorbloxTransparency")
					if stored ~= nil then
						original = tonumber(stored) or 0
					end
				end
				if original ~= nil then
					part.Transparency = original
					cosmeticCache.korblox[part] = nil
					setAttr(part, "ShaderVelardKorbloxTransparency", nil)
				end
			end
		end

		for _, child in ipairs(rig:GetChildren()) do
			if child:IsA("CharacterMesh") and child.BodyPart == Enum.BodyPart.RightLeg then
				local meshId = tostring(child.MeshId)
				if meshId == ("rbxassetid://" .. KORBLOX_MESH_ID)
					or tonumber(meshId) == KORBLOX_MESH_ID
					or string.find(child.Name:lower(), "korblox", 1, true) then
					child:Destroy()
				end
			end
		end
	end

	local function applyHeadlessHead(rig)
		local head = rig:FindFirstChild("Head")
		if not head or not head:IsA("BasePart") or head:IsA("MeshPart") then
			return
		end

		local specialMesh = head:FindFirstChildOfClass("SpecialMesh")
		if specialMesh then
			if cosmeticCache.headMesh[specialMesh] == nil then
				cosmeticCache.headMesh[specialMesh] = specialMesh.MeshId
				setAttr(specialMesh, "ShaderVelardHeadMeshId", specialMesh.MeshId)
			end
			specialMesh.MeshId = HEADLESS_HEAD_MESH
		end

		if cosmeticCache.headTransparency[head] == nil then
			cosmeticCache.headTransparency[head] = head.Transparency
			setAttr(head, "ShaderVelardHeadTransparency", head.Transparency)
		end
		head.Transparency = 1

		for _, child in ipairs(head:GetChildren()) do
			if child:IsA("Decal") then
				if cosmeticCache.decalTransparency[child] == nil then
					cosmeticCache.decalTransparency[child] = child.Transparency
					setAttr(child, "ShaderVelardHeadlessDecal", child.Transparency)
				end
				child.Transparency = 1
			end
		end
	end

	local function clearHeadlessHead(rig)
		local head = rig:FindFirstChild("Head")
		if not head then
			return
		end

		local headTransparency = cosmeticCache.headTransparency[head]
		if headTransparency == nil then
			local stored = getAttr(head, "ShaderVelardHeadTransparency")
			if stored ~= nil then
				headTransparency = tonumber(stored) or 0
			end
		end
		if headTransparency ~= nil then
			head.Transparency = headTransparency
			cosmeticCache.headTransparency[head] = nil
			setAttr(head, "ShaderVelardHeadTransparency", nil)
		end

		local specialMesh = head:FindFirstChildOfClass("SpecialMesh")
		if specialMesh then
			local meshId = cosmeticCache.headMesh[specialMesh]
			if meshId == nil then
				meshId = getAttr(specialMesh, "ShaderVelardHeadMeshId")
			end
			if meshId ~= nil then
				specialMesh.MeshId = meshId
				cosmeticCache.headMesh[specialMesh] = nil
				setAttr(specialMesh, "ShaderVelardHeadMeshId", nil)
			end
		end

		for _, child in ipairs(head:GetChildren()) do
			if child:IsA("Decal") then
				local decalTransparency = cosmeticCache.decalTransparency[child]
				if decalTransparency == nil then
					local stored = getAttr(child, "ShaderVelardHeadlessDecal")
					if stored ~= nil then
						decalTransparency = tonumber(stored) or 0
					end
				end
				if decalTransparency ~= nil then
					child.Transparency = decalTransparency
					cosmeticCache.decalTransparency[child] = nil
					setAttr(child, "ShaderVelardHeadlessDecal", nil)
				end
			end
		end
	end

	local function applyKorblox()
		local applied = 0
		for _, rig in ipairs(collectCosmeticRigs()) do
			local ok, result = pcall(applyKorbloxLeg, rig)
			if ok and result then
				applied = applied + 1
			end
		end
		return applied
	end

	local function clearKorblox()
		for _, rig in ipairs(collectCosmeticRigs()) do
			pcall(clearKorbloxLeg, rig)
		end
	end

	local function notifyKorbloxUnsupported()
		local message = "Korblox hanya berfungsi di rig R6/R15."
		if Effects.onNotify then
			pcall(Effects.onNotify, "ShaderVelard", message, 4)
		end
		setStatus(message)
	end

	local function applyHeadless()
		for _, rig in ipairs(collectCosmeticRigs()) do
			pcall(applyHeadlessHead, rig)
		end
	end

	local function clearHeadless()
		for _, rig in ipairs(collectCosmeticRigs()) do
			pcall(clearHeadlessHead, rig)
		end
	end

	local function applyCosmetics()
		if state.toggles.korblox then
			applyKorblox()
		end
		if state.toggles.headless then
			applyHeadless()
		end
	end

	local function clearCosmetics()
		clearKorblox()
		clearHeadless()
	end

	local function resetCosmeticCache()
		cosmeticCache.korblox = {}
		cosmeticCache.headMesh = {}
		cosmeticCache.headTransparency = {}
		cosmeticCache.decalTransparency = {}
	end

	-- Undo leftovers from a previous execution (the executor can reload the bundle
	-- while the old welded leg / hidden head is still in the DataModel).
	local function recoverStaleCosmetics()
		for _, rig in ipairs(collectCosmeticRigs()) do
			local staleLeg = rig:FindFirstChild("ShaderVelard_KorbloxLeg")
			if staleLeg then
				staleLeg:Destroy()
			end
			for _, name in ipairs({ "RightUpperLeg", "RightLowerLeg", "RightFoot" }) do
				local part = rig:FindFirstChild(name)
				if part and part:IsA("BasePart") then
					local stored = getAttr(part, "ShaderVelardKorbloxTransparency")
					if stored ~= nil then
						part.Transparency = tonumber(stored) or 0
						setAttr(part, "ShaderVelardKorbloxTransparency", nil)
					elseif staleLeg and part.Transparency >= 0.99 then
						part.Transparency = 0
					end
				end
			end
			local head = rig:FindFirstChild("Head")
			if head and head:IsA("BasePart") then
				local stored = getAttr(head, "ShaderVelardHeadTransparency")
				if stored ~= nil and head.Transparency >= 0.99 then
					pcall(clearHeadlessHead, rig)
				end
			end
		end
	end

	pcall(recoverStaleCosmetics)
	task.delay(1, function()
		if not isCurrentGeneration() then
			return
		end
		if state.toggles.headless or state.toggles.korblox then
			return
		end
		pcall(recoverStaleCosmetics)
	end)

	if characterConnection then
		characterConnection:Disconnect()
	end
	characterConnection = player.CharacterAdded:Connect(function()
		task.wait(0.5)
		if not isCurrentGeneration() then
			return
		end
		pcall(clearKorblox)
		pcall(clearHeadless)
		resetCosmeticCache()
		pcall(function()
			if state.toggles.angelAura then
				ensureAura()
			end
			if state.toggles.unusual then
				Effects._character.ensureUnusual()
			end
			if state.toggles.spoof then
				Effects._character.applySpoof()
			end
			pcall(Effects.refreshAccessories)
			if state.toggles.motionTrail then
				ensureTrail()
			end
		end)
		pcall(applyCosmetics)
		-- Remove Preset_Overlay clones left on the new character by an older run
		-- (accessories can stream in after the initial Workspace sweep).
		pcall(function()
			local currentCharacter = player.Character
			if currentCharacter then
				for _, descendant in ipairs(currentCharacter:GetDescendants()) do
					if descendant.Name == "Preset_Overlay" then
						descendant:Destroy()
					end
				end
			end
		end)
		-- Refresh the glossy pass a moment after spawn: some accessories are
		-- parented in stages, so this removes any overlay created too early.
		pcall(syncReflectionFloors)
	end)

	local function syncAllWorld()
		syncReflectionFloors()
		refreshCelHighlights()
		refreshNeon()
		syncClouds()
		syncWindVFX()
		if state.toggles.disco then
			ensureDisco()
		else
			clearDisco()
		end
		if not state.toggles.wind then
			safeSet(Workspace, "GlobalWind", globalWindOriginal)
		end
		updateVignette()
		updateLetterbox()
		updateChromatic()
		updateRain()
		updateScanlines()
		updateFlare()
		updateMotion()
		updateVhs()
		updateReShade()
		updateSnow()
		updateWatermark()
		local okFeatures, featureError = pcall(function()
			if state.toggles.angelAura then
				ensureAura()
			else
				clearAura()
			end
			if state.toggles.unusual then
				Effects._character.ensureUnusual()
			else
				Effects._character.clearUnusual()
			end
			if state.toggles.spoof then
				Effects._character.applySpoof()
			else
				Effects._character.clearSpoof()
			end
			pcall(Effects.refreshAccessories)
			if state.toggles.motionTrail then
				ensureTrail()
			else
				clearTrail()
			end
			if state.toggles.skyText then
				ensureSkyText()
			else
				clearSkyText()
			end
			updateUniversalParticles()
			if state.toggles.korblox then
				applyKorblox()
			else
				clearKorblox()
			end
			if state.toggles.headless then
				applyHeadless()
			else
				clearHeadless()
			end
		end)
		if not okFeatures then
			warn("[ShaderVelard] world feature sync failed: " .. tostring(featureError))
		end
	end

	local function startLightning()
		lightningToken = lightningToken + 1
		local token = lightningToken
		task.spawn(function()
			while state.toggles.lightning and token == lightningToken and isCurrentGeneration() do
				local frequency = math.clamp(state.sliders.lightningFrequency or 1, 0.2, 3)
				task.wait((math.random(35, 75) / 10) / frequency)
				if not state.toggles.lightning or token ~= lightningToken then
					break
				end
				local palette = state.dropdowns.lightningPalette or "White"
				local flashColor
				if palette == "Blue" then
					flashColor = Color3.fromRGB(180, 205, 255)
				elseif palette == "Purple" then
					flashColor = Color3.fromRGB(206, 180, 255)
				elseif palette == "Multi" then
					flashColor = Color3.fromHSV(math.random(), 0.6, 1)
				else
					flashColor = Color3.fromRGB(215, 228, 255)
				end
				local bloom = ensurePost("Bloom")
				local bloomIntensity = 0
				if bloom then
					local ok, value = pcall(function()
						return bloom.Intensity
					end)
					if ok and type(value) == "number" then
						bloomIntensity = value
					end
				end
				local brightness = Lighting.Brightness
				local ambient = Lighting.Ambient
				safeSet(Lighting, "Brightness", brightness + 3)
				safeSet(Lighting, "Ambient", flashColor)
				if bloom then
					safeSet(bloom, "Intensity", bloomIntensity + 1.5)
				end
				task.wait(0.06)
				Effects.recompute()
				task.wait(0.07)
				if not state.toggles.lightning or token ~= lightningToken then
					break
				end
				safeSet(Lighting, "Brightness", brightness + 1.8)
				if bloom then
					safeSet(bloom, "Intensity", bloomIntensity + 0.8)
				end
				task.wait(0.045)
				Effects.recompute()
				safeSet(Lighting, "Ambient", ambient)
			end
		end)
	end

	function Effects.setToggle(name, value)
		value = value == true
		-- Locked features (Headless after agreeing to the warning) stay on for the
		-- whole session. Refuse the change and re-assert the enabled state.
		if lockedToggles[name] and not value then
			state.toggles[name] = true
			if Effects.onNotify then
				pcall(Effects.onNotify, "Locked for this session", tostring(name) .. " is permanently enabled until you rejoin the game.", 5)
			end
			notifyChanged()
			setStatus("Feature locked for this session")
			return false
		end
		-- Always (re)apply, even when the value is unchanged. If an effect got
		-- out of sync with the UI (respawn, game script, second load), clicking
		-- the toggle off must actually clear it instead of early-returning.
		state.toggles[name] = value

		local applied, applyError = pcall(function()
		if name == "wetFloor" or name == "ssr" or name == "banano" or name == "rtx"
			or name == "rtxWrapObjects" or name == "rtxWrapTerrain"
			or name == "bananoWrapObjects" or name == "bananoWrapTerrain" then
			syncReflectionFloors()
			if state.sliders.textureDetail < 0.999 then
				Effects._applyTextureDetail()
			end
		elseif name == "celShading" then
			refreshCelHighlights()
		elseif name == "neon" then
			refreshNeon()
		elseif name == "clouds" then
			syncClouds()
		elseif name == "windVFX" then
			syncWindVFX()
		elseif name == "disco" then
			if value then
				ensureDisco()
			else
				clearDisco()
			end
		elseif name == "discoAura" then
			if not value and discoAuraLight then
				discoAuraLight:Destroy()
				discoAuraLight = nil
			end
		elseif name == "wind" then
			if not value then
				safeSet(Workspace, "GlobalWind", globalWindOriginal)
			end
		elseif name == "rain" then
			updateRain()
		elseif name == "nightVision" then
			updateScanlines()
		elseif name == "lensFlare" then
			updateFlare()
		elseif name == "vignette" then
			updateVignette()
		elseif name == "letterbox" then
			updateLetterbox()
		elseif name == "chromatic" then
			updateChromatic()
		elseif name == "motionBlur" then
			updateMotion()
		elseif name == "vhs" then
			updateVhs()
		elseif name == "reShade" then
			updateReShade()
		elseif name == "winterTerrain" then
			updateSnow()
		elseif name == "watermark" then
			updateWatermark()
		elseif name == "hideSun" then
			syncSky()
		elseif name == "lightning" then
			if value then
				startLightning()
			else
				lightningToken = lightningToken + 1
				Effects.recompute()
			end
		elseif name == "angelAura" then
			if value then
				ensureAura()
			else
				clearAura()
			end
		elseif name == "motionTrail" then
			if value then
				ensureTrail()
			else
				clearTrail()
			end
		elseif name == "skyText" then
			if value then
				ensureSkyText()
			else
				clearSkyText()
			end
		elseif name == "korblox" then
			logCosmeticRigs("korblox")
			if value then
				if applyKorblox() == 0 then
					notifyKorbloxUnsupported()
				end
			else
				clearKorblox()
			end
		elseif name == "unusual" then
			if value then
				if not Effects._character.ensureUnusual() and Effects.onNotify then
					pcall(Effects.onNotify, "Unusual Effect", "Character not ready. Respawn or try again in a second.", 4)
				end
			else
				Effects._character.clearUnusual()
			end
		elseif name == "spoof" then
			if value then
				if not Effects._character.applySpoof() and Effects.onNotify then
					pcall(Effects.onNotify, "Spoof Appearance", "Character not ready. Respawn or try again in a second.", 4)
				end
			else
				Effects._character.clearSpoof()
			end
		elseif name == "accessoryHidden" then
			Effects.refreshAccessories()
		elseif name == "freecam" then
			if value then
				if not Effects._character.startFreecam() then
					state.toggles.freecam = false
					if Effects.onNotify then
						pcall(Effects.onNotify, "Freecam", "No camera available.", 4)
					end
				end
			else
				Effects._character.stopFreecam()
			end
		elseif name == "antiAFK" then
			Effects._character.applyAntiAfk(value)
		elseif name == "headless" then
			logCosmeticRigs("headless")
			if value then
				local applied = applyHeadless()
				if applied == 0 and Effects.onNotify then
					pcall(Effects.onNotify, "Headless", "No character rig found yet. Respawn or toggle again in a second.", 4)
				end
			else
				local restored = clearHeadless()
				if restored == 0 and Effects.onNotify then
					pcall(Effects.onNotify, "Headless", "No character rig found. Rejoin the game once if an old session left the head hidden.", 5)
				end
				-- Some games re-apply the avatar appearance a moment after it is
				-- changed. Re-assert the restored head briefly so switching the
				-- toggle off always brings the head back.
				for _, delay in ipairs({ 0.15, 0.4, 0.9, 1.6 }) do
					task.delay(delay, function()
						if not state.toggles.headless and not Effects._destroyed then
							pcall(clearHeadless)
						end
					end)
				end
			end
		elseif name == "universalSnow" or name == "sparkles" then
			updateUniversalParticles()
		elseif name == "skyAnimation" then
			skyTimer = 0
		end
		end)
		if not applied then
			warn("[ShaderVelard] toggle '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end

		if name == "nightVision"
			or name == "monochrome"
			or name == "celShading"
			or name == "greenScreen"
			or name == "fakeSSAO"
			or name == "hideSun"
			or name == "lightning"
			or name == "bokeh"
			or name == "vhs"
			or name == "reShade"
			or name == "winterTerrain"
			or name == "evadeLighting"
			or name == "disco"
			or name == "discoBloom"
			or name == "smartAtmosphere"
			or name == "rainbow"
			or name == "policeFlash" then
			Effects.recompute()
		end

		notifyChanged()
		setStatus((value and "Enabled " or "Disabled ") .. name)
	end

	function Effects.setSlider(name, value)
		state.sliders[name] = value

		local applied, applyError = pcall(function()
		if name == "brightness" then
			state.base.Lighting.Brightness = value
		elseif name == "exposure" then
			state.base.Lighting.ExposureCompensation = value
		elseif name == "bloom" then
			state.base.Bloom.Intensity = value
		elseif name == "saturation" then
			state.base.ColorCorrection.Saturation = value
		elseif name == "contrast" then
			state.base.ColorCorrection.Contrast = value
		elseif name == "fogDensity" then
			state.base.Atmosphere.Density = value
		elseif name == "clockTime" then
			state.base.Lighting.ClockTime = value
		elseif name == "envDiffuse" then
			state.base.Lighting.EnvironmentDiffuseScale = value
		elseif name == "envSpecular" then
			state.base.Lighting.EnvironmentSpecularScale = value
		elseif name == "shadowSoftness" then
			state.base.Lighting.ShadowSoftness = value
		elseif name == "ambientR" or name == "ambientG" or name == "ambientB" then
			state.base.Lighting.Ambient = Color3.fromRGB(
				state.sliders.ambientR, state.sliders.ambientG, state.sliders.ambientB
			)
		elseif name == "outdoorR" or name == "outdoorG" or name == "outdoorB" then
			state.base.Lighting.OutdoorAmbient = Color3.fromRGB(
				state.sliders.outdoorR, state.sliders.outdoorG, state.sliders.outdoorB
			)
		elseif name == "bloomSize" then
			state.base.Bloom.Size = value
		elseif name == "bloomThreshold" then
			state.base.Bloom.Threshold = value
		elseif name == "ccBrightness" then
			state.base.ColorCorrection.Brightness = value
		elseif name == "fogHaze" then
			state.base.Atmosphere.Haze = value
		elseif name == "fogGlare" then
			state.base.Atmosphere.Glare = value
		elseif name == "fogDecay" then
			state.base.Atmosphere.Decay = Color3.fromRGB(value, value, value)
		elseif name == "sunRaysIntensity" then
			state.base.SunRays.Intensity = value
		elseif name == "sunRaysSpread" then
			state.base.SunRays.Spread = value
		elseif name == "textureDetail" then
			if state.sliders.textureDetail >= 0.999 then
				Effects._clearTextureDetail()
			else
				Effects._applyTextureDetail()
			end
			return
		elseif name == "fov" then
			local camera = Workspace.CurrentCamera
			if camera then
				camera.FieldOfView = value
			end
			return
		elseif name == "vignette" then
			updateVignette()
			return
		elseif name == "chromaticStrength" then
			updateChromatic()
			return
		elseif name == "rainIntensity" then
			updateRain()
			return
		elseif name == "cloudCover" or name == "cloudDensity" then
			syncClouds()
			return
		elseif name == "glossyReflectance" or name == "ssrDetail" or name == "ssrOpacity"
			or name == "ssrThickness" or name == "bananoLevel" or name == "rtxLevel" then
			applyGlossy()
			return
		elseif name == "bananoRadius" or name == "bananoOffset"
			or name == "rtxRadius" or name == "rtxOffset" then
			refreshGlossy()
			return
		elseif name == "motionBlurStrength" or name == "windStrength" or name == "discoSpeed"
			or name == "skySpeed" or name == "cloudSpeed" or name == "lightningFrequency"
			or name == "snowIntensity" then
			return
		elseif name == "reShadeIntensity" then
			updateReShade()
			Effects.recompute()
			return
		elseif name == "vhsIntensity" then
			updateVhs()
			return
		elseif name == "neonIntensity" then
			for _, highlight in pairs(neonHighlights) do
				if highlight and highlight.Parent then
					highlight.OutlineTransparency = math.clamp(0.3 - state.sliders.neonIntensity * 0.25, 0, 0.8)
				end
			end
			return
		elseif name == "discoIntensity" then
			Effects.recompute()
			return
		elseif name == "bokehFocus" or name == "bokehIntensity" then
			if state.toggles.bokeh then
				Effects.recompute()
			end
			return
		elseif name == "auraSize" or name == "auraSpeed" then
			updateAuraStyle()
			return
		elseif name == "unusualSize" then
			Effects._character.updateUnusualStyle()
			return
		elseif name == "trailLifetime" then
			updateTrailStyle()
			return
		elseif name == "skyTextSize" or name == "skyTextThickness" then
			updateSkyTextStyle()
			return
		elseif name == "sparkleRate" or name == "snowRate" then
			updateUniversalParticles()
			return
		elseif name == "skyTextHeight" or name == "skyTextDistance" or name == "skyTextAnimSpeed"
			or name == "rainbowSpeed" or name == "policeFlashSpeed" then
			return
		end
		end)
		if not applied then
			warn("[ShaderVelard] slider '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end

		Effects.recompute()
	end

	function Effects.setDropdown(name, value)
		if state.dropdowns[name] == value then
			return
		end
		state.dropdowns[name] = value

		local applied, applyError = pcall(function()
		if name == "glossyMode" then
			applyGlossy()
		elseif name == "globalShadows" then
			Effects.recompute()
		elseif name == "sunTint" then
			Effects.recompute()
		elseif name == "discoMode" or name == "lightningPalette" then
			return
		elseif name == "auraColor" then
			updateAuraStyle()
			Effects._character.updateUnusualStyle()
		elseif name == "trailColor" then
			updateTrailStyle()
		elseif name == "unusualStyle" then
			Effects._character.updateUnusualStyle()
		elseif name == "spoofStyle" then
			if state.toggles.spoof then
				Effects._character.clearSpoof()
				Effects._character.applySpoof()
			end
		elseif name == "accessory" then
			Effects.refreshAccessories()
		elseif name == "skyTextColor" then
			updateSkyTextStyle()
		elseif name == "skyTextAnim" then
			return
		end
		end)
		if not applied then
			warn("[ShaderVelard] dropdown '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end

		notifyChanged()
		setStatus("Set " .. name .. " to " .. tostring(value))
	end

	function Effects.setSkyText(text)
		text = tostring(text or "")
		if #text > 80 then
			text = string.sub(text, 1, 80)
		end
		state.skyTextString = text
		local ok, err = pcall(function()
			if skyTextLabel then
				skyTextLabel.Text = text
			end
		end)
		if not ok then
			warn("[ShaderVelard] sky text update failed: " .. tostring(err))
		end
		setStatus("Sky text updated")
		return text
	end

	-- ===== Preset share codes =====
	-- The share code is a one-line base64 snapshot of
	-- the whole visual state (base look, toggles, sliders, dropdowns and sky) so a
	-- code can be pasted into another session without losing precision.
	Effects._share = (function()
	local ShareCode = {
		prefix = "SV1:",
		alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",
		lookup = {},
	}
	for index = 1, #ShareCode.alphabet do
		ShareCode.lookup[string.sub(ShareCode.alphabet, index, index)] = index - 1
	end

	function ShareCode.base64Encode(data)
		local out = {}
		for index = 1, #data, 3 do
			local a = string.byte(data, index) or 0
			local b = string.byte(data, index + 1)
			local c = string.byte(data, index + 2)
			local value = a * 65536 + (b or 0) * 256 + (c or 0)
			local c1 = math.floor(value / 262144) % 64
			local c2 = math.floor(value / 4096) % 64
			local c3 = math.floor(value / 64) % 64
			local c4 = value % 64
			out[#out + 1] = string.sub(ShareCode.alphabet, c1 + 1, c1 + 1)
			out[#out + 1] = string.sub(ShareCode.alphabet, c2 + 1, c2 + 1)
			out[#out + 1] = b and string.sub(ShareCode.alphabet, c3 + 1, c3 + 1) or "="
			out[#out + 1] = c and string.sub(ShareCode.alphabet, c4 + 1, c4 + 1) or "="
		end
		return table.concat(out)
	end

	function ShareCode.base64Decode(data)
		data = string.gsub(tostring(data or ""), "%s+", "")
		if #data == 0 or #data % 4 ~= 0 then
			return nil, "Corrupted Base64 payload in share code!"
		end
		local out = {}
		for index = 1, #data, 4 do
			local chunk = string.sub(data, index, index + 3)
			local c1 = ShareCode.lookup[string.sub(chunk, 1, 1)]
			local c2 = ShareCode.lookup[string.sub(chunk, 2, 2)]
			local c3 = ShareCode.lookup[string.sub(chunk, 3, 3)]
			local c4 = ShareCode.lookup[string.sub(chunk, 4, 4)]
			if not c1 or not c2 then
				return nil, "Corrupted Base64 payload in share code!"
			end
			local padding = 0
			if string.sub(chunk, 3, 3) == "=" then
				c3, c4, padding = 0, 0, 2
			elseif string.sub(chunk, 4, 4) == "=" then
				c4, padding = 0, 1
			end
			if not c3 or not c4 then
				return nil, "Corrupted Base64 payload in share code!"
			end
			local value = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
			out[#out + 1] = string.char(math.floor(value / 65536) % 256)
			if padding < 2 then
				out[#out + 1] = string.char(math.floor(value / 256) % 256)
			end
			if padding < 1 then
				out[#out + 1] = string.char(value % 256)
			end
		end
		return table.concat(out)
	end

	function ShareCode.isColor3(value)
		local ok, kind = pcall(function()
			return typeof(value)
		end)
		return ok and kind == "Color3"
	end

	function ShareCode.writeLengthPrefixed(out, tag, text)
		out[#out + 1] = tag .. tostring(#text) .. ":" .. text
	end

	function ShareCode.serializeValue(value, out)
		local kind = type(value)
		if value == nil then
			out[#out + 1] = "z"
		elseif kind == "boolean" then
			out[#out + 1] = value and "b1" or "b0"
		elseif kind == "number" then
			local text
			if value ~= value then
				text = "nan"
			elseif value == math.huge then
				text = "inf"
			elseif value == -math.huge then
				text = "-inf"
			else
				text = string.format("%.17g", value)
			end
			ShareCode.writeLengthPrefixed(out, "n", text)
		elseif kind == "string" then
			ShareCode.writeLengthPrefixed(out, "s", value)
		elseif kind == "table" then
			local keys = {}
			for key in pairs(value) do
				if type(key) ~= "string" then
					error("share code tables must use string keys")
				end
				keys[#keys + 1] = key
			end
			table.sort(keys)
			out[#out + 1] = "t" .. tostring(#keys) .. ":"
			for _, key in ipairs(keys) do
				ShareCode.serializeValue(key, out)
				ShareCode.serializeValue(value[key], out)
			end
		elseif ShareCode.isColor3(value) then
			local ok, red = pcall(function()
				return value.R
			end)
			local green, blue
			if ok then
				pcall(function()
					green = value.G
					blue = value.B
				end)
			end
			if not ok or not green or not blue then
				error("unsupported Color3 value")
			end
			out[#out + 1] = string.format(
				"c%d,%d,%d;",
				math.floor(red * 255 + 0.5),
				math.floor(green * 255 + 0.5),
				math.floor(blue * 255 + 0.5)
			)
		else
			error("unsupported share code value: " .. kind)
		end
	end

	function ShareCode.readLengthPrefixed(data, position)
		local colon = string.find(data, ":", position, true)
		if not colon then
			return nil, position
		end
		local length = tonumber(string.sub(data, position, colon - 1))
		if not length or length < 0 then
			return nil, position
		end
		local start = colon + 1
		return string.sub(data, start, start + length - 1), start + length
	end

	function ShareCode.deserializeValue(data, position)
		local tag = string.sub(data, position, position)
		if tag == "" then
			return nil, position, "unexpected end of share code"
		end
		position = position + 1

		if tag == "z" then
			return nil, position
		elseif tag == "b" then
			local bit = string.sub(data, position, position)
			position = position + 1
			if bit ~= "0" and bit ~= "1" then
				return nil, position, "invalid boolean"
			end
			return bit == "1", position
		elseif tag == "n" then
			local text, nextPosition = ShareCode.readLengthPrefixed(data, position)
			if not text then
				return nil, position, "invalid number"
			end
			local number
			if text == "nan" then
				number = 0 / 0
			elseif text == "inf" then
				number = math.huge
			elseif text == "-inf" then
				number = -math.huge
			else
				number = tonumber(text)
			end
			if number == nil then
				return nil, nextPosition, "invalid number"
			end
			return number, nextPosition
		elseif tag == "s" then
			local text, nextPosition = ShareCode.readLengthPrefixed(data, position)
			if not text then
				return nil, position, "invalid string"
			end
			return text, nextPosition
		elseif tag == "c" then
			local semicolon = string.find(data, ";", position, true)
			if not semicolon then
				return nil, position, "invalid Color3"
			end
			local red, green, blue = string.match(string.sub(data, position, semicolon - 1), "^(%d+),(%d+),(%d+)$")
			if not red then
				return nil, semicolon + 1, "invalid Color3"
			end
			return Color3.fromRGB(tonumber(red), tonumber(green), tonumber(blue)), semicolon + 1
		elseif tag == "t" then
			local colon = string.find(data, ":", position, true)
			if not colon then
				return nil, position, "invalid table"
			end
			local count = tonumber(string.sub(data, position, colon - 1))
			if not count or count < 0 then
				return nil, colon + 1, "invalid table"
			end
			local result = {}
			position = colon + 1
			for _ = 1, count do
				local key
				key, position = ShareCode.deserializeValue(data, position)
				if key == nil or position > #data + 1 then
					return nil, position, "truncated table"
				end
				local value
				value, position = ShareCode.deserializeValue(data, position)
				result[key] = value
			end
			return result, position
		end
		return nil, position, "unknown share code tag"
	end

	-- Minimal JSON codec for Joevan JOEVAN# payloads. It intentionally supports
	-- only JSON data (objects, arrays, strings, numbers, booleans, null) plus
	-- Color3 objects; that is exactly what share codes contain.
	local function jsonEscape(text)
		text = tostring(text)
		text = string.gsub(text, "\\", "\\\\")
		text = string.gsub(text, '"', '\\"')
		text = string.gsub(text, "\n", "\\n")
		text = string.gsub(text, "\r", "\\r")
		text = string.gsub(text, "\t", "\\t")
		return '"' .. text .. '"'
	end

	local function jsonIsArray(value)
		local count = 0
		for key in pairs(value) do
			if type(key) ~= "number" then
				return false
			end
			count = count + 1
		end
		if count == 0 then
			return false
		end
		for index = 1, count do
			if value[index] == nil then
				return false
			end
		end
		return true
	end

	function ShareCode.jsonEncode(value)
		local kind = type(value)
		if value == nil then
			return "null"
		elseif kind == "boolean" then
			return value and "true" or "false"
		elseif kind == "number" then
			if value ~= value or value == math.huge or value == -math.huge then
				return "0"
			end
			return string.format("%.17g", value)
		elseif kind == "string" then
			return jsonEscape(value)
		elseif ShareCode.isColor3(value) then
			return string.format(
				'{"__type":"Color3","r":%d,"g":%d,"b":%d}',
				math.floor(value.R * 255 + 0.5),
				math.floor(value.G * 255 + 0.5),
				math.floor(value.B * 255 + 0.5)
			)
		elseif kind == "table" then
			local out = {}
			if jsonIsArray(value) then
				for index = 1, #value do
					out[#out + 1] = ShareCode.jsonEncode(value[index])
				end
				return "[" .. table.concat(out, ",") .. "]"
			end
			local keys = {}
			for key in pairs(value) do
				keys[#keys + 1] = tostring(key)
			end
			table.sort(keys)
			for _, key in ipairs(keys) do
				out[#out + 1] = jsonEscape(key) .. ":" .. ShareCode.jsonEncode(value[key])
			end
			return "{" .. table.concat(out, ",") .. "}"
		end
		error("unsupported JSON value: " .. kind)
	end

	function ShareCode.jsonDecode(text)
		text = tostring(text or "")
		local position = 1
		local parseValue

		local function skipWhitespace()
			while true do
				local ch = string.sub(text, position, position)
				if ch == " " or ch == "\t" or ch == "\r" or ch == "\n" then
					position = position + 1
				else
					break
				end
			end
		end

		local function parseString()
			position = position + 1
			local out = {}
			while position <= #text do
				local ch = string.sub(text, position, position)
				if ch == '"' then
					position = position + 1
					return table.concat(out)
				elseif ch == "\\" then
					local esc = string.sub(text, position + 1, position + 1)
					position = position + 2
					if esc == "n" then out[#out + 1] = "\n"
					elseif esc == "r" then out[#out + 1] = "\r"
					elseif esc == "t" then out[#out + 1] = "\t"
					elseif esc == "b" then out[#out + 1] = "\b"
					elseif esc == "f" then out[#out + 1] = "\f"
					elseif esc == "u" then
						local code = tonumber(string.sub(text, position, position + 3), 16)
						position = position + 4
						out[#out + 1] = (code and code < 128) and string.char(code) or "?"
					else out[#out + 1] = esc end
				else
					out[#out + 1] = ch
					position = position + 1
				end
			end
			error("unterminated JSON string")
		end

		local function parseNumber()
			local start = position
			while position <= #text do
				local ch = string.sub(text, position, position)
				if string.find("+-0123456789.eE", ch, 1, true) then
					position = position + 1
				else
					break
				end
			end
			return tonumber(string.sub(text, start, position - 1))
		end

		local function parseObject()
			position = position + 1
			local result = {}
			skipWhitespace()
			if string.sub(text, position, position) == "}" then
				position = position + 1
				return result
			end
			while true do
				skipWhitespace()
				local key = parseString()
				skipWhitespace()
				position = position + 1
				result[key] = parseValue()
				skipWhitespace()
				local ch = string.sub(text, position, position)
				position = position + 1
				if ch == "}" then
					return result
				end
			end
		end

		local function parseArray()
			position = position + 1
			local result = {}
			skipWhitespace()
			if string.sub(text, position, position) == "]" then
				position = position + 1
				return result
			end
			while true do
				result[#result + 1] = parseValue()
				skipWhitespace()
				local ch = string.sub(text, position, position)
				position = position + 1
				if ch == "]" then
					return result
				end
			end
		end

		parseValue = function()
			skipWhitespace()
			local ch = string.sub(text, position, position)
			if ch == "{" then
				local object = parseObject()
				if object.__type == "Color3" then
					return Color3.fromRGB(object.r or 0, object.g or 0, object.b or 0)
				end
				return object
			elseif ch == "[" then
				return parseArray()
			elseif ch == '"' then
				return parseString()
			elseif string.sub(text, position, position + 3) == "true" then
				position = position + 4
				return true
			elseif string.sub(text, position, position + 4) == "false" then
				position = position + 5
				return false
			elseif string.sub(text, position, position + 3) == "null" then
				position = position + 4
				return nil
			end
			return parseNumber()
		end

		local value = parseValue()
		return value
	end

	return ShareCode
	end)()

	function Effects._buildShareSnapshot()
		local exportToggles = copy(state.toggles)
		-- Tools, not part of a visual look, must not be enabled by pasting a code.
		exportToggles.freecam = nil
		exportToggles.antiAFK = nil
		return {
			v = 1,
			base = state.base,
			toggles = exportToggles,
			sliders = state.sliders,
			dropdowns = state.dropdowns,
			skyName = state.skyName,
			skyIndex = state.skyIndex,
			customSky = state.customSky,
			skyIsCustom = state.skyIsCustom == true,
			customSkyMeta = state.customSkyMeta,
			skyTextString = state.skyTextString,
			presetName = state.presetName,
			discoColorizeLamps = state.discoColorizeLamps == true,
			liteMode = state.liteMode == true,
		}
	end

	function Effects.exportPresetCode(format)
		local snapshot = Effects._buildShareSnapshot()
		if format == "sv1" or format == "SV1" then
			return Effects.exportLegacyCode()
		end
		-- Joevan V15: "JOEVAN#" .. base64(JSONEncode(captureCurrentPresetState())).
		local ok, encoded = pcall(function()
			return Effects._share.base64Encode(Effects._share.jsonEncode(snapshot))
		end)
		if not ok then
			warn("[ShaderVelard] share code export failed: " .. tostring(encoded))
			return nil
		end
		return "JOEVAN#" .. encoded
	end

	function Effects.exportLegacyCode()
		local snapshot = Effects._buildShareSnapshot()
		local ok, encoded = pcall(function()
			local out = {}
			Effects._share.serializeValue(snapshot, out)
			return Effects._share.base64Encode(table.concat(out))
		end)
		if not ok then
			warn("[ShaderVelard] share code export failed: " .. tostring(encoded))
			return nil
		end
		return Effects._share.prefix .. encoded
	end

	function Effects.copyToClipboard(text)
		text = tostring(text or "")
		local copied = false
		for _, name in ipairs({ "setclipboard", "toclipboard" }) do
			local fn = rawget(_G, name)
			if type(fn) == "function" then
				local ok = pcall(fn, text)
				if ok then
					copied = true
					break
				end
			end
		end
		return copied
	end

	function Effects.importPresetCode(code)
		code = string.gsub(tostring(code or ""), "%s+", "")
		local joevanPrefix = "JOEVAN#"
		if string.sub(code, 1, #joevanPrefix) == joevanPrefix then
			local raw, decodeError = Effects._share.base64Decode(string.sub(code, #joevanPrefix + 1))
			if not raw then
				return false, decodeError
			end
			local ok, payload = pcall(Effects._share.jsonDecode, raw)
			if not ok or type(payload) ~= "table" then
				return false, "Corrupted Base64 payload in share code!"
			end
			-- Our exporter writes the full remake snapshot, which is also valid
			-- Joevan JSON. Route it through the existing SV1 apply path.
			if payload.base or payload.toggles or payload.sliders then
				local okEncode, encoded = pcall(function()
					local out = {}
					Effects._share.serializeValue(payload, out)
					return Effects._share.base64Encode(table.concat(out))
				end)
				if not okEncode then
					return false, "Corrupted Base64 payload in share code!"
				end
				return Effects.importPresetCode(Effects._share.prefix .. encoded)
			end
			return Effects.applyJoevanPresetObject(payload)
		end
		local prefix = Effects._share.prefix
		if string.sub(code, 1, #prefix) ~= prefix then
			return false, "Invalid share code (expected JOEVAN# or SV1: prefix)"
		end

		local raw, decodeError = Effects._share.base64Decode(string.sub(code, #prefix + 1))
		if not raw then
			return false, decodeError
		end
		local ok, snapshot, position = pcall(function()
			local value, nextPosition = Effects._share.deserializeValue(raw, 1)
			return value, nextPosition
		end)
		if not ok or type(snapshot) ~= "table" or snapshot.v ~= 1 then
			return false, "Corrupted Base64 payload in share code!"
		end
		if tonumber(position) and position <= #raw then
			return false, "Corrupted Base64 payload in share code!"
		end

		local applyOk, applyError = pcall(function()
			Effects.resetAll()

			state.base = copy(Config.NeutralLook)
			if type(snapshot.base) == "table" then
				merge(state.base, snapshot.base)
			end

			if type(snapshot.toggles) == "table" then
				for key, value in pairs(snapshot.toggles) do
					if type(key) == "string" and type(value) == "boolean" then
						state.toggles[key] = value
					end
				end
			end
			if type(snapshot.sliders) == "table" then
				for key, value in pairs(snapshot.sliders) do
					if type(key) == "string" and type(value) == "number" then
						state.sliders[key] = value
					end
				end
			end
			if type(snapshot.dropdowns) == "table" then
				for key, value in pairs(snapshot.dropdowns) do
					if type(key) == "string" and (type(value) == "string" or type(value) == "number") then
						state.dropdowns[key] = value
					end
				end
			end

			if type(snapshot.discoColorizeLamps) == "boolean" then
				state.discoColorizeLamps = snapshot.discoColorizeLamps
			end

			state.customSky = { Bk = "", Dn = "", Ft = "", Lf = "", Rt = "", Up = "" }
			if type(snapshot.customSky) == "table" then
				for key, value in pairs(snapshot.customSky) do
					if type(key) == "string" and type(value) == "string" then
						state.customSky[key] = value
					end
				end
			end
			state.customSkyMeta = nil
			if type(snapshot.customSkyMeta) == "table" then
				state.customSkyMeta = {}
				for key, value in pairs(snapshot.customSkyMeta) do
					if type(key) == "string" then
						state.customSkyMeta[key] = value
					end
				end
			end
			state.skyTextString = tostring(snapshot.skyTextString or state.skyTextString or "")
			state.presetName = tostring(snapshot.presetName or "Imported")
			if type(snapshot.skyIndex) == "number" then
				state.skyIndex = math.clamp(math.floor(snapshot.skyIndex), 1, math.max(#Config.Skyboxes, 1))
			end
			if type(snapshot.liteMode) == "boolean" then
				state.liteMode = snapshot.liteMode
				glossyCandidates = nil
				glossyCacheBuilt = false
			end
			for key in pairs(lockedToggles) do
				state.toggles[key] = true
			end

			if snapshot.skyIsCustom == true or snapshot.skyName == "Custom" or snapshot.skyName == "Preset Sky" then
				Effects.applyCustomSky(state.customSky, snapshot.skyName, state.customSkyMeta)
			elseif type(snapshot.skyName) == "string" then
				Effects.applySky(snapshot.skyName)
			end

			if state.toggles.lightning then
				startLightning()
			end
			syncAllWorld()
			Effects.recompute()
		end)
		if not applyOk then
			warn("[ShaderVelard] share code apply failed: " .. tostring(applyError))
			return false, tostring(applyError)
		end

		notifyChanged()
		setStatus("Imported shader preset applied successfully")
		return true
	end

	-- ===== Saved custom presets =====
	-- Wrapped in an IIFE so this feature gets its own local-variable budget.
	Effects._presetStore = (function()
	local PRESET_FILE = "ShaderVelard_Presets.txt"
	local customPresets = {}
	local customPresetsLoaded = false

	local function trimText(value)
		return (string.gsub(tostring(value or ""), "^%s*(.-)%s*$", "%1"))
	end

	local function cleanPresetName(name)
		name = trimText(name)
		if name == "" then
			return nil, "Please enter a preset name."
		end
		name = string.gsub(name, "[%c|]", " ")
		name = trimText(name)
		if name == "" then
			return nil, "Preset name is invalid (only illegal chars)."
		end
		if #name > 48 then
			name = string.sub(name, 1, 48)
		end
		return name
	end

	local function readCustomPresetFile()
		if customPresetsLoaded then
			return
		end
		customPresetsLoaded = true
		if type(readfile) ~= "function" then
			return
		end
		if type(isfile) == "function" then
			local okFile, exists = pcall(isfile, PRESET_FILE)
			if not okFile or not exists then
				return
			end
		end
		local ok, data = pcall(readfile, PRESET_FILE)
		if not ok or type(data) ~= "string" then
			return
		end
		for line in string.gmatch(data, "[^\r\n]+") do
			local name, code = string.match(line, "^(.-)|(SV1:.*)$")
			if name and code and trimText(name) ~= "" then
				customPresets[trimText(name)] = code
			end
		end
	end

	local function writeCustomPresetFile()
		if type(writefile) ~= "function" then
			return false, "Your executor does not support saving files"
		end
		local lines = {}
		for name, code in pairs(customPresets) do
			table.insert(lines, name .. "|" .. code)
		end
		table.sort(lines)
		local ok, err = pcall(writefile, PRESET_FILE, table.concat(lines, "\n"))
		if not ok then
			return false, "Failed to save preset: " .. tostring(err)
		end
		return true
	end

	local function getCustomPresetNames()
		readCustomPresetFile()
		local names = {}
		for name in pairs(customPresets) do
			table.insert(names, name)
		end
		table.sort(names)
		return names
	end

	local function refreshCustomPresetFile()
		customPresets = {}
		customPresetsLoaded = false
		readCustomPresetFile()
		return getCustomPresetNames()
	end

	local function saveCustomPreset(name)
		local clean, nameError = cleanPresetName(name)
		if not clean then
			return false, nameError
		end
		local code = Effects.exportPresetCode()
		if not code then
			return false, "Preset capture engine not ready!"
		end
		readCustomPresetFile()
		customPresets[clean] = code
		local wrote, writeError = writeCustomPresetFile()
		if wrote then
			setStatus("Preset file '" .. PRESET_FILE .. "' saved")
			return true, "Preset file '" .. PRESET_FILE .. "' saved."
		end
		-- Keep the preset usable for this session even without executor file APIs.
		setStatus("Preset saved for this session (" .. tostring(writeError) .. ")")
		return true, "Preset saved for this session. " .. tostring(writeError or "")
	end

	local function applyCustomPreset(name)
		readCustomPresetFile()
		name = trimText(name)
		local code = customPresets[name]
		if not code then
			return false, "Failed to load preset: preset not found"
		end
		local ok, err = Effects.importPresetCode(code)
		if ok then
			state.presetName = name
			notifyChanged()
			setStatus("Preset set to: " .. name)
		end
		return ok, err
	end

	local function deleteCustomPreset(name)
		readCustomPresetFile()
		name = trimText(name)
		if customPresets[name] == nil then
			return false, "Failed to delete presets."
		end
		customPresets[name] = nil
		local wrote, writeError = writeCustomPresetFile()
		if not wrote then
			return false, tostring(writeError)
		end
		setStatus("Preset '" .. name .. "' deleted.")
		return true
	end

	local function deleteAllCustomPresets()
		readCustomPresetFile()
		customPresets = {}
		local wrote, writeError = writeCustomPresetFile()
		if not wrote then
			setStatus("Preset(s) deleted for this session.")
			return true, "Preset(s) deleted for this session."
		end
		setStatus("Preset(s) deleted.")
		return true, "Preset(s) deleted."
	end
	return {
		getNames = getCustomPresetNames,
		refresh = refreshCustomPresetFile,
		save = saveCustomPreset,
		apply = applyCustomPreset,
		delete = deleteCustomPreset,
		deleteAll = deleteAllCustomPresets,
	}
	end)()

	function Effects.getCustomPresetNames()
		return Effects._presetStore.getNames()
	end

	function Effects.refreshCustomPresets()
		return Effects._presetStore.refresh()
	end

	function Effects.saveCustomPreset(name)
		return Effects._presetStore.save(name)
	end

	function Effects.applyCustomPreset(name)
		return Effects._presetStore.apply(name)
	end

	function Effects.deleteCustomPreset(name)
		return Effects._presetStore.delete(name)
	end

	function Effects.deleteAllCustomPresets()
		return Effects._presetStore.deleteAll()
	end

	function Effects._applyPresetData(preset)
		if type(preset) ~= "table" then
			return false
		end
		preset.Name = preset.Name or preset.Key or "Imported"
		local look = copy(Config.NeutralLook)
		merge(look, preset.Look)
		state.base = look
		state.presetName = preset.Name

		-- Character cosmetics are not part of a lighting preset. Keep whatever the
		-- player already enabled (Korblox/Headless stay locked on) instead of
		-- silently resetting them to off when a preset is applied.
		local keepKorblox = state.toggles.korblox == true
		local keepHeadless = state.toggles.headless == true

		-- Joevan applyPreset starts with resetAllEffects(true) (FUNCTION #400,
		-- pc 0-2), which clears every effect toggle including the RTX/Banano wrap
		-- toggles. Only the remake's session utilities/character cosmetics are kept.
		for key in pairs(state.toggles) do
			if key ~= "freecam" and key ~= "antiAFK" then
				state.toggles[key] = false
			end
		end
		for key in pairs(lockedToggles) do
			state.toggles[key] = true
		end
		state.dropdowns = copy(initialDropdowns)
		state.sliders = copy(initialSliders)

		state.sliders.brightness = math.clamp(look.Lighting.Brightness, 0, 5)
		state.sliders.exposure = math.clamp(look.Lighting.ExposureCompensation, -2, 2)
		state.sliders.bloom = math.clamp(look.Bloom.Intensity, 0, 5)
		state.sliders.saturation = math.clamp(look.ColorCorrection.Saturation, -1, 1)
		state.sliders.contrast = math.clamp(look.ColorCorrection.Contrast, -1, 1)
		state.sliders.fogDensity = math.clamp(look.Atmosphere.Density, 0, 1)
		state.sliders.clockTime = math.clamp(look.Lighting.ClockTime or 14, 0, 24)
		state.sliders.envDiffuse = math.clamp(look.Lighting.EnvironmentDiffuseScale or 0.5, 0, 1)
		state.sliders.envSpecular = math.clamp(look.Lighting.EnvironmentSpecularScale or 0.5, 0, 1)
		state.sliders.shadowSoftness = math.clamp(look.Lighting.ShadowSoftness or 0.25, 0, 1)
		state.sliders.ambientR = math.floor((look.Lighting.Ambient or Color3.new()).R * 255 + 0.5)
		state.sliders.ambientG = math.floor((look.Lighting.Ambient or Color3.new()).G * 255 + 0.5)
		state.sliders.ambientB = math.floor((look.Lighting.Ambient or Color3.new()).B * 255 + 0.5)
		state.sliders.outdoorR = math.floor((look.Lighting.OutdoorAmbient or Color3.new()).R * 255 + 0.5)
		state.sliders.outdoorG = math.floor((look.Lighting.OutdoorAmbient or Color3.new()).G * 255 + 0.5)
		state.sliders.outdoorB = math.floor((look.Lighting.OutdoorAmbient or Color3.new()).B * 255 + 0.5)
		state.sliders.bloomSize = math.clamp(look.Bloom.Size or 24, 0, 60)
		state.sliders.bloomThreshold = math.clamp(look.Bloom.Threshold or 1.1, 0, 3)
		state.sliders.ccBrightness = math.clamp(look.ColorCorrection.Brightness or 0, -1, 1)
		state.sliders.fogHaze = math.clamp(look.Atmosphere.Haze or 0, 0, 10)
		state.sliders.fogGlare = math.clamp(look.Atmosphere.Glare or 0, 0, 5)
		state.sliders.fogDecay = math.floor((look.Atmosphere.Decay or Color3.new()).R * 255 + 0.5)
		state.sliders.sunRaysIntensity = math.clamp(look.SunRays.Intensity or 0.05, 0, 1)
		state.sliders.sunRaysSpread = math.clamp(look.SunRays.Spread or 0.4, 0, 1)
		state.dropdowns.globalShadows = (look.Lighting.GlobalShadows == false) and "Off" or "On"

		if preset.Sliders then
			for key, value in pairs(preset.Sliders) do
				state.sliders[key] = value
			end
		end
		if preset.GlossyIntensity ~= nil then
			state.sliders.glossyIntensity = preset.GlossyIntensity
		end
		state.discoColorizeLamps = preset.DiscoColorizeLamps == true
		if preset.Dropdowns then
			for key, value in pairs(preset.Dropdowns) do
				state.dropdowns[key] = value
			end
		end
		state.base.ColorCorrection.Saturation = math.clamp(state.sliders.saturation, -1, 1)
		state.base.ColorCorrection.Contrast = math.clamp(state.sliders.contrast, -1, 1)
		lightningToken = lightningToken + 1
		if preset.Toggles then
			for key, value in pairs(preset.Toggles) do
				state.toggles[key] = value
			end
			if preset.Toggles.skyAnimation then
				skyTimer = 0
			end
			if preset.Toggles.lightning then
				startLightning()
			end
		end
		for key in pairs(lockedToggles) do
			state.toggles[key] = true
		end
		state.toggles.korblox = keepKorblox
		state.toggles.headless = keepHeadless

		if preset.SkyFaces then
			-- Match Joevan's setSkybox(preset.Key, preset.Skybox): always write the
			-- six raw faces. SkyName is display metadata only.
			Effects.applyCustomSky(preset.SkyFaces, preset.SkyName or "Preset Sky", {
				StarCount = preset.StarCount,
				CelestialBodiesShown = preset.CelestialBodiesShown,
				SunTextureId = preset.SunTextureId,
				MoonTextureId = preset.MoonTextureId,
			})
		elseif preset.Sky then
			Effects.applySky(preset.Sky)
		else
			-- Every built-in preset carries a skybox. Reset the sky for effect-only
			-- looks so a previous preset cannot bleed through.
			Effects.applySky("Default")
		end

		local applied, applyError = pcall(function()
			syncAllWorld()
			Effects.recompute()
		end)
		if not applied then
			warn("[ShaderVelard] preset '" .. tostring(preset.Name) .. "' failed: " .. tostring(applyError))
		end
		notifyChanged()
		setStatus("Applied preset: " .. preset.Name)
		return true
	end

	function Effects.applyPreset(name)
		local preset = Config.findPreset(name)
		if not preset then
			return
		end
		return Effects._applyPresetData(preset)
	end

	-- Convert a decoded Joevan share-code object into the remake's preset shape.
	-- Joevan's encoder writes the active preset fields (Lighting, Material,
	-- GlossyIntensity, Skybox, SSR, ...), not the remake's snapshot keys.
	function Effects.applyJoevanPresetObject(source)
		if type(source) ~= "table" then
			return false, "Share code payload is not a preset table"
		end
		local preset = {
			Key = source.Key or "Imported",
			Name = source.Name or source.Key or "Imported Preset",
			Desc = source.Desc,
			AccentColor = source.AccentColor,
			Material = source.Material,
			Reflectance = source.Reflectance,
			GlossyIntensity = source.GlossyIntensity,
			DiscoColorizeLamps = source.DiscoColorizeLamps == true,
			Look = {},
			Toggles = {},
			Sliders = {},
			Dropdowns = {},
		}
		for _, key in ipairs({ "Lighting", "Atmosphere", "Bloom", "ColorCorrection", "DepthOfField", "SunRays" }) do
			if type(source[key]) == "table" then
				preset.Look[key] = source[key]
			end
		end
		if type(source.Look) == "table" then
			for key, value in pairs(source.Look) do
				preset.Look[key] = value
			end
		end
		if type(source.Toggles) == "table" then preset.Toggles = copy(source.Toggles) end
		if type(source.Sliders) == "table" then preset.Sliders = copy(source.Sliders) end
		if type(source.Dropdowns) == "table" then preset.Dropdowns = copy(source.Dropdowns) end
		-- Map the Joevan boolean fields used by hand-written/spoofed codes.
		if source.SSR == true then preset.Toggles.ssr = true end
		if source.Rain == true then preset.Toggles.rain = true end
		if source.AnimatedSkybox == true then preset.Toggles.skyAnimation = true end
		if source.Chromatic == true then preset.Toggles.chromatic = true end
		if source.FakeSSAO == true then preset.Toggles.fakeSSAO = true end
		if source.ReShade == true then preset.Toggles.reShade = true end
		if source.LensFlare == true then preset.Toggles.lensFlare = true end
		if source.DiscoLamp == true then preset.Toggles.disco = true end
		if source.DiscoMode then preset.Dropdowns.discoMode = source.DiscoMode end
		if source.DiscoIntensity then preset.Sliders.discoIntensity = source.DiscoIntensity end
		if source.DiscoSpeed then preset.Sliders.discoSpeed = source.DiscoSpeed end
		if type(source.SkyFaces) == "table" then preset.SkyFaces = source.SkyFaces end
		if source.SkyName then preset.SkyName = source.SkyName end
		if type(source.Skybox) == "table" then
			preset.SkyFaces = {}
			for _, key in ipairs({ "Bk", "Dn", "Ft", "Lf", "Rt", "Up" }) do
				preset.SkyFaces[key] = source.Skybox["Skybox" .. key] or source.Skybox[key]
			end
			preset.SkyName = source.ActiveSkyboxName
		end
		return Effects._applyPresetData(preset)
	end

	function Effects.resetAll()
		lightningToken = lightningToken + 1
		state.toggles = {
			wetFloor = false,
			ssr = false,
			vignette = false,
			letterbox = false,
			chromatic = false,
			nightVision = false,
			monochrome = false,
			celShading = false,
			greenScreen = false,
			lensFlare = false,
			fakeSSAO = false,
			hideSun = false,
			rain = false,
			clouds = false,
			lightning = false,
			wind = false,
			disco = false,
			discoBloom = false,
			discoAura = false,
			skyAnimation = false,
			-- P2 Smart Atmosphere (non-premium Joevan toggle, MAIN pc 9082-9096).
			-- Default OFF so preset parity is unaffected.
			smartAtmosphere = false,
			bokeh = false,
			motionBlur = false,
			vhs = false,
			reShade = false,
			watermark = false,
			neon = false,
			evadeLighting = false,
			winterTerrain = false,
			windVFX = false,
			banano = false,
			rtx = false,
			angelAura = false,
			motionTrail = false,
			skyText = false,
			universalSnow = false,
			sparkles = false,
			rainbow = false,
			policeFlash = false,
			korblox = false,
			headless = false,
			unusual = false,
			spoof = false,
			accessoryHidden = false,
			freecam = false,
			antiAFK = false,
			rtxWrapObjects = true,
			rtxWrapTerrain = true,
			bananoWrapObjects = true,
			bananoWrapTerrain = true,
		}
		if lockedToggles.headless then
			state.toggles.headless = true
		end

		clearGlossy()
		Effects._clearTextureDetail()
		clearCelHighlights()
		clearNeon()
		clearDisco()
		Effects._character.stopFreecam()
		Effects._character.applyAntiAfk(false)
		if discoAuraLight then
			discoAuraLight:Destroy()
			discoAuraLight = nil
		end
		clearAura()
		Effects._character.clearUnusual()
		Effects._character.clearSpoof()
		Effects._character.clearAccessories()
		Effects._character.resetEmotes()
		clearTrail()
		clearSkyText()
		clearCosmetics()
		resetCosmeticCache()
		if lockedToggles.headless then
			pcall(applyHeadless)
		end
		if universalSnowPart then
			universalSnowPart:Destroy()
			universalSnowPart = nil
			universalSnowEmitter = nil
			sparkleEmitter = nil
		end
		syncWindVFX()
		clearClouds()
		restoreTerrain()

		for key, value in pairs(lightingOriginal) do
			safeSet(Lighting, key, value)
		end

		for _, post in ipairs(POST_CLASSES) do
			local entry = posts[post.key]
			if entry then
				if entry.created then
					if entry.instance and entry.instance.Parent then
						entry.instance:Destroy()
					end
					posts[post.key] = nil
				else
					for key, value in pairs(entry.props) do
						safeSet(entry.instance, key, value)
					end
				end
			end
		end

		-- ColorCorrection.Enabled is the one post property that is not part of the
		-- preset Look tables (writeLook forces it on). Restore the game's original
		-- value explicitly so a reset can never leave it stuck at true.
		local ccEntry = posts.ColorCorrection
		if ccEntry and not ccEntry.created and ccEntry.instance and ccEntry.props.Enabled ~= nil then
			safeSet(ccEntry.instance, "Enabled", ccEntry.props.Enabled)
		end

		if skyInstance then
			if skyWasCreated then
				skyInstance:Destroy()
				skyInstance = nil
				skyWasCreated = false
			elseif skyOriginal then
				for key, value in pairs(skyOriginal) do
					safeSet(skyInstance, key, value)
				end
			end
		end

		local camera = Workspace.CurrentCamera
		if camera then
			safeSet(camera, "FieldOfView", initialFov)
		end

		state.base = copy(initialBase)
		state.sliders = copy(initialSliders)
		state.dropdowns = copy(initialDropdowns)
		state.discoColorizeLamps = false
		state.presetName = "None"
		state.skyName = "Default"
		state.skyIndex = 1
		state.skyIsCustom = false
		state.customSkyMeta = nil

		vignetteContainer.Visible = false
		letterboxTop.Visible = false
		letterboxBottom.Visible = false
		chromaticContainer.Visible = false
		scanlineContainer.Visible = false
		rainContainer.Visible = false
		flareContainer.Visible = false
		motionContainer.Visible = false
		if Effects._motionBlur then
			Effects._motionBlur.Enabled = false
			Effects._motionBlur.Size = 0
		end
		vhsContainer.Visible = false
		reShadeContainer.Visible = false
		snowContainer.Visible = false
		watermarkLabel.Visible = false
		if discoPart then
			discoPart:Destroy()
			discoPart = nil
		end
		if discoAuraLight then
			discoAuraLight:Destroy()
			discoAuraLight = nil
		end

		notifyChanged()
		setStatus("All shader effects reset")
	end

	function Effects.setLiteMode(value)
		state.liteMode = value == true
		glossyCandidates = nil
		glossyCacheBuilt = false
		clearGlossy(true)
		if state.toggles.wetFloor or state.toggles.ssr or state.toggles.banano or state.toggles.rtx then
			applyGlossy()
		end
		if state.toggles.neon then
			refreshNeon()
		end
		if state.toggles.celShading then
			refreshCelHighlights()
		end
		if state.toggles.universalSnow or state.toggles.sparkles then
			updateUniversalParticles()
		end
		if state.toggles.angelAura then
			updateAuraStyle()
		end
		setStatus("Lite Mode " .. (state.liteMode and "enabled" or "disabled"))
		notifyChanged()
		return state.liteMode
	end

	function Effects.destroy()
		if Effects._destroyed then
			return
		end
		Effects._destroyed = true
		Effects.onChanged = nil
		Effects.onStatus = nil
		Effects.onNotify = nil
		Effects.onSkyChanged = nil
		lightningToken = lightningToken + 1
		if stepConnection then
			stepConnection:Disconnect()
			stepConnection = nil
		end
		if characterConnection then
			characterConnection:Disconnect()
			characterConnection = nil
		end
		Effects.resetAll()
		if overlay and overlay.Parent then
			overlay:Destroy()
		end
		overlay = nil
	end

	function Effects.getPresetNames()
		local names = {}
		for _, preset in ipairs(Config.Presets) do
			table.insert(names, preset.Name)
		end
		return names
	end

	function Effects.getSkyNames()
		local names = {}
		for _, sky in ipairs(Config.Skyboxes) do
			table.insert(names, sky.Name)
		end
		return names
	end

	Effects._stepErrorLogged = false
	stepConnection = RunService.RenderStepped:Connect(function(deltaTime)
		if not isCurrentGeneration() then
			if stepConnection then
				stepConnection:Disconnect()
				stepConnection = nil
			end
			return
		end
		local ok, err = pcall(function()
		clock = clock + deltaTime

		if state.toggles.freecam then
			Effects._character.updateFreecam(deltaTime)
		end

		Effects._tickSkyAnimation(deltaTime)

		if state.toggles.korblox or state.toggles.headless then
			cosmeticTimer = cosmeticTimer + deltaTime
			if cosmeticTimer >= 1.5 then
				cosmeticTimer = 0
				applyCosmetics()
			end
		else
			cosmeticTimer = 0
		end

		if state.toggles.chromatic then
			local strength = state.sliders.chromaticStrength
			local offset = math.sin(clock * 3.2) * math.clamp(strength, 0, 3) * 2
			local thickness = chromaticLeft.AbsoluteSize.X
			chromaticLeft.Position = UDim2.new(0, -offset, 0, 0)
			chromaticRight.Position = UDim2.new(1, -thickness + offset, 0, 0)
		end

		if state.toggles.rain then
			local intensity = math.clamp(state.sliders.rainIntensity / 100, 0.1, 1)
			local viewport = overlay.AbsoluteSize.Y
			for _, drop in ipairs(rainStreaks) do
				drop.y = drop.y + (drop.speed * intensity * deltaTime) / math.max(viewport, 1)
				if drop.y > 1.1 then
					drop.y = -0.12
					drop.x = math.random()
				end
				drop.frame.Position = UDim2.new(drop.x, 0, drop.y, 0)
			end
		end

		if state.toggles.lensFlare then
			local camera = Workspace.CurrentCamera
			if camera then
				local sunDirection = Lighting:GetSunDirection()
				local worldPoint = camera.CFrame.Position + sunDirection * 1200
				local screenPoint, onScreen = camera:WorldToViewportPoint(worldPoint)
				if onScreen and screenPoint.Z > 0 then
					flareContainer.Visible = true
					local pos = UDim2.fromOffset(screenPoint.X, screenPoint.Y)
					flareOuter.Position = pos
					flareMid.Position = pos + UDim2.fromOffset(26, -18)
					flareCore.Position = pos
					local pulse = 0.9 + math.sin(clock * 1.7) * 0.06
					flareOuter.Size = UDim2.fromOffset(180 * pulse, 180 * pulse)
					flareMid.Size = UDim2.fromOffset(76 * pulse, 76 * pulse)
				else
					flareContainer.Visible = false
				end
			end
		end

		if state.toggles.disco then
			local camera = Workspace.CurrentCamera
			if not discoPart or not discoPart.Parent then
				ensureDisco()
			end
			local intensity = state.sliders.discoIntensity
			local mode = state.dropdowns.discoMode
			if discoPart and camera then
				discoPart.CFrame = camera.CFrame * CFrame.new(0, 5, -8)
				for index, light in ipairs(discoLights) do
					if light and light.Parent then
						local hue
						if mode == "Warm Pulse" then
							hue = 0.06 + math.sin(clock * 2 + index) * 0.04
						elseif mode == "Cool Pulse" then
							hue = 0.55 + math.sin(clock * 2 + index) * 0.05
						elseif mode == "Strobe" then
							hue = (index % 2 == 0) and 0 or 0.66
						elseif mode == "Neon Cyberpunk" then
							hue = (index % 2 == 0) and 0.5 or 0.85
						else
							hue = (clock * 0.18 * state.sliders.discoSpeed + index / 3) % 1
						end
						light.Color = Color3.fromHSV((hue % 1 + 1) % 1, 0.85, 1)
						light.Brightness = intensity * (0.8 + math.sin(clock * 3 + index) * 0.25)
						light.Range = 22 + intensity * 1.6 + math.sin(clock * 2 + index) * 5
					end
				end
			end

			Effects._colorizeDiscoLamps(intensity, mode)

			if state.toggles.discoAura then
				local character = player.Character
				local root = character and character:FindFirstChild("HumanoidRootPart")
				if root then
					if not discoAuraLight or not discoAuraLight.Parent then
						discoAuraLight = Instance.new("PointLight")
						discoAuraLight.Name = "ShaderVelard_DiscoAura"
						discoAuraLight.Range = 14
						discoAuraLight.Shadows = false
						discoAuraLight.Parent = root
					end
					local auraHue = (clock * 0.2 * state.sliders.discoSpeed) % 1
					discoAuraLight.Color = Color3.fromHSV(auraHue, 0.8, 1)
					discoAuraLight.Brightness = intensity * 0.6
				end
			elseif discoAuraLight then
				discoAuraLight:Destroy()
				discoAuraLight = nil
			end
		end

		if state.toggles.clouds then
			local clouds = terrain:FindFirstChildOfClass("Clouds")
			if clouds then
					-- Joevan MovingClouds tick (FUNCTION #546 pc 32-54):
				-- Cover = clamp(_cloudCover + sin(os.clock()*0.3)*0.04, 0.1, 0.95).
				-- CloudSpeed drives the wind angle, not the cover amplitude/frequency.
				local cover = math.clamp(state.sliders.cloudCover + math.sin(clock * 0.3) * 0.04, 0.1, 0.95)
				safeSet(clouds, "Cover", cover)
			end
		end

		if state.toggles.wind then
			local strength = state.sliders.windStrength / 100
			local wind = Vector3.new(
				math.sin(clock * 0.35) * 18 * strength,
				math.sin(clock * 0.21) * 3 * strength,
				math.cos(clock * 0.28) * 18 * strength
			)
			safeSet(Workspace, "GlobalWind", wind)
		end

		local camera = Workspace.CurrentCamera
		if camera then
			local look = camera.CFrame.LookVector
			if lastCameraLook then
				local delta = (look - lastCameraLook).Magnitude
				cameraMotion = cameraMotion * 0.88 + (delta / math.max(deltaTime, 0.001)) * 0.12
			end
			lastCameraLook = look
		end

		if state.toggles.motionBlur then
			local strength = math.clamp(state.sliders.motionBlurStrength * math.min(cameraMotion * 5, 1), 0, 1)
			local blur = Effects._ensureMotionBlur()
			blur.Size = strength * 8
			blur.Enabled = strength > 0.01
			for _, streak in ipairs(motionStreaks) do
				streak.BackgroundTransparency = 1
			end
		else
			if Effects._motionBlur then
				Effects._motionBlur.Enabled = false
				Effects._motionBlur.Size = 0
			end
			for _, streak in ipairs(motionStreaks) do
				streak.BackgroundTransparency = 1
			end
		end

		if state.toggles.vhs then
			vhsBand.Position = UDim2.new(0, 0, (clock * 0.09) % 1, 0)
			vhsBand.BackgroundTransparency = 0.85 + math.sin(clock * 24) * 0.07
			vhsRec.TextTransparency = (math.sin(clock * 4) > 0) and 0 or 0.55
			if math.floor(clock) ~= vhsSecond then
				vhsSecond = math.floor(clock)
				vhsTime.Text = localTimeString()
			end
		end

		if state.toggles.reShade and math.floor(clock * 10) ~= reShadeFrame then
			reShadeFrame = math.floor(clock * 10)
			for _, line in ipairs(reShadeGrain) do
				line.Position = UDim2.new(math.random(), 0, math.random(), 0)
			end
		end

		if state.toggles.winterTerrain then
			local intensity = math.clamp(state.sliders.snowIntensity / 100, 0.1, 1)
			local viewport = math.max(overlay.AbsoluteSize.Y, 1)
			for _, flake in ipairs(snowFlakes) do
				flake.y = flake.y + (flake.speed * intensity * deltaTime) / viewport
				if flake.y > 1.05 then
					flake.y = -0.05
					flake.x = math.random()
				end
				flake.frame.Position = UDim2.new(
					flake.x + math.sin(clock * 0.8 + flake.sway) * 0.012,
					0,
					flake.y,
					0
				)
			end
		end

		if state.toggles.angelAura then
			local root = getRootPart()
			if root and (not auraAttachment or auraAttachment.Parent ~= root) then
				ensureAura()
			end
			if auraEmitter and state.dropdowns.auraColor == "Rainbow" then
				local hue = (clock * 0.15 * math.max(state.sliders.auraSpeed, 0.1)) % 1
				local color = Color3.fromHSV(hue, 0.7, 1)
				auraEmitter.Color = ColorSequence.new(color)
				if auraLight then
					auraLight.Color = color
				end
			end
		end

		if state.toggles.unusual then
			Effects._character.tickUnusual()
		end

		if state.toggles.motionTrail then
			local root = getRootPart()
			if root and (not trailInstance or trailInstance.Parent ~= root) then
				ensureTrail()
			end
			if trailInstance and state.dropdowns.trailColor == "Rainbow" then
				local color = Color3.fromHSV((clock * 0.2) % 1, 0.7, 1)
				trailInstance.Color = ColorSequence.new(color, color)
			end
		end

		if state.toggles.skyText and skyTextPart then
			local camera = Workspace.CurrentCamera
			if camera then
				local position = camera.CFrame.Position
					+ Vector3.new(0, state.sliders.skyTextHeight, 0)
					+ camera.CFrame.LookVector * state.sliders.skyTextDistance
				local base = CFrame.lookAt(position, camera.CFrame.Position)
				local anim = state.dropdowns.skyTextAnim or "None"
				local speed = math.max(state.sliders.skyTextAnimSpeed or 1, 0.05)
				if anim == "Scroll X" then
					local travel = ((clock * speed * 40) % 800) - 400
					base = base + base.RightVector * travel
				elseif anim == "Scroll Y" then
					local travel = ((clock * speed * 40) % 800) - 400
					base = base + base.UpVector * travel
				elseif anim == "Wave" then
					base = base + base.UpVector * (math.sin(clock * speed * 2) * 30)
				elseif anim == "Rotate" then
					base = base * CFrame.Angles(0, 0, clock * speed)
				end
				local baseSize = math.clamp(state.sliders.skyTextSize, 20, 400)
				local pulse = (anim == "Pulse") and (1 + math.sin(clock * speed * 3) * 0.25) or 1
				skyTextPart.Size = Vector3.new(baseSize * pulse, baseSize * 0.4 * pulse, 0.2)
				skyTextPart.CFrame = base
			end
		end

		if (state.toggles.universalSnow or state.toggles.sparkles) and universalSnowPart then
			local camera = Workspace.CurrentCamera
			if camera then
				universalSnowPart.CFrame = camera.CFrame * CFrame.new(0, 14, 0)
			end
		end

		if state.toggles.rainbow then
			local hue = (clock * 0.08 * math.max(state.sliders.rainbowSpeed, 0.05)) % 1
			local top = Color3.fromHSV(hue, 0.55, 1)
			local bottom = Color3.fromHSV((hue + 0.5) % 1, 0.55, 1)
			safeSet(Lighting, "ColorShift_Top", top)
			safeSet(Lighting, "ColorShift_Bottom", bottom)
			local correction = ensurePost("ColorCorrection")
			if correction then
				safeSet(correction, "TintColor", top)
			end
		end

		if state.toggles.policeFlash then
			local flip = math.sin(clock * (2 + state.sliders.policeFlashSpeed * 3)) > 0
			local color = flip and Color3.fromRGB(255, 48, 48) or Color3.fromRGB(48, 96, 255)
			safeSet(Lighting, "Ambient", color)
			local correction = ensurePost("ColorCorrection")
			if correction then
				safeSet(correction, "TintColor", color)
			end
			local bloom = ensurePost("Bloom")
			if bloom then
				local base = state.base.Bloom and state.base.Bloom.Intensity or 0.4
				safeSet(bloom, "Intensity", base + (flip and 1.1 or 0.15))
			end
		end

		if state.toggles.neon then
			for _, highlight in pairs(neonHighlights) do
				if highlight and highlight.Parent then
					highlight.OutlineColor = Color3.fromHSV((clock * 0.15) % 1, 0.9, 1)
				end
			end
		end

		if state.toggles.windVFX and windVFXEmitter and windVFXPart then
			if camera then
				windVFXPart.CFrame = camera.CFrame * CFrame.new(0, 6, -18)
			end
			local strength = state.sliders.windStrength
			windVFXEmitter.Rate = particleCap(8 + strength * 0.6)
			windVFXEmitter.Speed = NumberRange.new(6 + strength * 0.15, 14 + strength * 0.35)
			local okWind, currentWind = pcall(function()
				return Workspace.GlobalWind
			end)
			if okWind and typeof(currentWind) == "Vector3" then
				safeSet(windVFXEmitter, "Acceleration", currentWind * 1.5)
			end
		end
		end)
		if not ok and not Effects._stepErrorLogged then
			stepErrorLogged = true
			warn("[ShaderVelard] RenderStepped error: " .. tostring(err))
		end
	end)

	notifyChanged()
	setStatus("ShaderVelard ready - no key required")

	return Effects
end

-- ===== Module: UI =====
__modules["UI"] = function()
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")
	local TweenService = game:GetService("TweenService")
	local UserInputService = game:GetService("UserInputService")
	local RunService = game:GetService("RunService")

	local Config = __require("Config")
	local Effects = __require("Effects")

	local player = Players.LocalPlayer
	local playerGui = player:WaitForChild("PlayerGui")
	local theme = Config.Theme
	local fonts = Config.Fonts

	local function detectMobile()
		if not UserInputService.TouchEnabled then
			return false
		end
		if not UserInputService.KeyboardEnabled then
			return true
		end
		local camera = workspace.CurrentCamera
		if camera and camera.ViewportSize.X > 0 and camera.ViewportSize.X < 820 then
			return true
		end
		return false
	end

	local isMobile = detectMobile()
	local HEADER_H = isMobile and 40 or 46
	local TABBAR_H = 38
	local SIDEBAR_W = isMobile and 0 or 176
	local STATUS_H = isMobile and 0 or 28
	local EDGE = isMobile and 8 or 12
	local HEADER_BTN_Y = isMobile and 7 or 10
	local TITLE_Y = isMobile and 8 or 11
	local TITLE_SIZE = isMobile and 16 or 18
	local VERSION_Y = isMobile and 24 or 28
	local VERSION_SIZE = isMobile and 9 or 10

	local UI = {}
	local selectTab
	local setWindowVisible
	local refresh

	local function make(className, properties, parent)
		local instance = Instance.new(className)
		for key, value in pairs(properties or {}) do
			instance[key] = value
		end
		instance.Parent = parent
		return instance
	end

	local function addCorner(instance, radius)
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, radius)
		corner.Parent = instance
		return corner
	end

	local function addStroke(instance, color, thickness, transparency)
		local stroke = Instance.new("UIStroke")
		stroke.Color = color or theme.Stroke
		stroke.Thickness = thickness or 1
		stroke.Transparency = transparency or 0
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		stroke.Parent = instance
		return stroke
	end

	local function addGradient(instance, colorSequence, rotation)
		local gradient = Instance.new("UIGradient")
		gradient.Color = colorSequence
		gradient.Rotation = rotation or 0
		gradient.Parent = instance
		return gradient
	end

	local function tween(instance, info, goals)
		local animation = TweenService:Create(instance, info, goals)
		animation:Play()
		return animation
	end

	-- 8-bit crown sprite. "X" = body pixel, "o" = jewel pixel, "." = empty.
	local CROWN_ART = {
		".X.....X.....X.",
		".X.....X.....X.",
		".XX...XXX...XX.",
		".XXX.XXXXX.XXX.",
		".XXXXXXXXXXXXX.",
		".XXXXXXXXXXXXX.",
		".XoXXoXXoXXoXX.",
		".XXXXXXXXXXXXX.",
		".XXXXXXXXXXXXX.",
		".XXXXXXXXXXXXX.",
		"..XXXXXXXXXXX..",
	}

	local function createPixelCrown(parent, position, pixelSize, bodyColor, jewelColor, zIndex)
		local rows = #CROWN_ART
		local columns = #CROWN_ART[1]
		local crown = make("Frame", {
			Name = "PixelCrown",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(columns * pixelSize, rows * pixelSize),
			Position = position,
			ZIndex = zIndex or 4,
		}, parent)

		for y = 1, rows do
			local line = CROWN_ART[y]
			for x = 1, columns do
				local glyph = line:sub(x, x)
				local color
				if glyph == "X" then
					color = bodyColor
				elseif glyph == "o" then
					color = jewelColor
				end
				if color then
					make("Frame", {
						Name = string.format("Px_%d_%d", x, y),
						Size = UDim2.fromOffset(pixelSize, pixelSize),
						Position = UDim2.fromOffset((x - 1) * pixelSize, (y - 1) * pixelSize),
						BackgroundColor3 = color,
						BorderSizePixel = 0,
						ZIndex = zIndex or 4,
					}, crown)
				end
			end
		end

		return crown
	end

	-- Prefer CoreGui: many live games' anti-cheat clears unknown ScreenGuis sitting
	-- in PlayerGui, which makes the menu vanish right after it is created. CoreGui
	-- is not touched by that. Fall back to PlayerGui if CoreGui is unavailable.
	local function pickGuiParent()
		local ok, coreGui = pcall(function()
			return game:GetService("CoreGui")
		end)
		if ok and coreGui then
			return coreGui
		end
		return playerGui
	end

	local guiParent = pickGuiParent()
	local previousGui = guiParent:FindFirstChild("ShaderVelardUI")
			or playerGui:FindFirstChild("ShaderVelardUI")
	if previousGui then
		previousGui:Destroy()
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = "ShaderVelardUI"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 200
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.Parent = guiParent

	-- Some games detach/destroy injected guis. If ours is ever removed from the
	-- chosen parent while not intentionally destroyed, re-attach it. The watchdog
	-- stops once UI.destroy() sets UI._destroyed.
	gui.AncestryChanged:Connect(function(_, parent)
		if UI and UI._destroyed then
			return
		end
		if parent ~= guiParent then
			pcall(function()
				gui.Parent = guiParent
			end)
		end
	end)

	local window = make("Frame", {
		Name = "Window",
		Size = isMobile and UDim2.fromScale(0.82, 0.72) or UDim2.fromOffset(780, 580),
		Position = UDim2.fromScale(0.5, 0.5),
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = theme.Bg,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = 2,
	}, gui)
	addStroke(window, theme.Stroke, 1, 0)

	if isMobile then
		local windowConstraint = Instance.new("UISizeConstraint")
		windowConstraint.MaxSize = Vector2.new(780, 600)
		windowConstraint.MinSize = Vector2.new(240, 220)
		windowConstraint.Parent = window
	end

	local windowScale = Instance.new("UIScale")
	windowScale.Scale = 1
	windowScale.Parent = window

	local header = make("Frame", {
		Name = "Header",
		Size = UDim2.new(1, 0, 0, HEADER_H),
		Position = UDim2.fromScale(0, 0),
		BackgroundTransparency = 1,
		Active = true,
