		TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(TITLE_X - 1, VERSION_Y),
		Size = UDim2.fromOffset(240, 14),
		ZIndex = 4,
	}, header)

	local closeButton = make("TextButton", {
		Name = "Close",
		Text = "X",
		Font = fonts.Bold,
		TextSize = 13,
		TextColor3 = theme.SubText,
		BackgroundColor3 = theme.Card,
		AutoButtonColor = false,
		Size = UDim2.fromOffset(isMobile and 30 or 26, isMobile and 30 or 26),
		Position = UDim2.new(1, isMobile and -40 or -38, 0, HEADER_BTN_Y),
		BorderSizePixel = 0,
		ZIndex = 4,
	}, header)
	addCorner(closeButton, 8)

	local minimizeButton = make("TextButton", {
		Name = "Minimize",
		Text = "_",
		Font = fonts.Bold,
		TextSize = 13,
		TextColor3 = theme.SubText,
		BackgroundColor3 = theme.Card,
		AutoButtonColor = false,
		Size = UDim2.fromOffset(isMobile and 30 or 26, isMobile and 30 or 26),
		Position = UDim2.new(1, isMobile and -76 or -70, 0, HEADER_BTN_Y),
		BorderSizePixel = 0,
		ZIndex = 4,
	}, header)
	addCorner(minimizeButton, 8)

	local sidebar
	local tabList
	local tabListHorizontal = false
	if isMobile then
		local tabBar = make("Frame", {
			Name = "TabBar",
			Size = UDim2.new(1, 0, 0, TABBAR_H),
			Position = UDim2.fromOffset(0, HEADER_H),
			BackgroundColor3 = theme.BgSoft,
			BorderSizePixel = 0,
			ZIndex = 3,
		}, window)
		make("Frame", {
			Name = "TabBarDivider",
			Size = UDim2.new(1, 0, 0, 1),
