	}, statusBar)

	local presetLabel = make("TextLabel", {
		Name = "Preset",
		Text = "Preset: None",
		Font = fonts.Medium,
		TextSize = 10,
		TextColor3 = theme.Accent,
		TextXAlignment = Enum.TextXAlignment.Right,
		BackgroundTransparency = 1,
		Position = UDim2.new(1, -150, 0, 6),
		Size = UDim2.fromOffset(136, 16),
		ZIndex = 4,
	}, statusBar)

	local toggles = {}
	local sliders = {}
	local dropdowns = {}
	local presetCards = {}
	local interfaceState = {
		floatingButton = true,
		notifications = true,
		iconOpacity = 1,
		iconSize = 1,
		guiOpacity = 1,
		uiScale = 1,
		hud = false,
		keybinds = {
			toggleUI = Enum.KeyCode.V,
			resetEffects = Enum.KeyCode.Nine,
			toggleHUD = Enum.KeyCode.H,
			freecam = Enum.KeyCode.Eight,
			nextPreset = Enum.KeyCode.P,
			nextSkybox = Enum.KeyCode.K,
		},
	}
	local keybindButtons = {}
	local listeningKeybind = nil
	local KEY_LABELS = {
		[Enum.KeyCode.Zero] = "0",
		[Enum.KeyCode.One] = "1",
		[Enum.KeyCode.Two] = "2",
		[Enum.KeyCode.Three] = "3",
		[Enum.KeyCode.Four] = "4",
		[Enum.KeyCode.Five] = "5",
		[Enum.KeyCode.Six] = "6",
		[Enum.KeyCode.Seven] = "7",
		[Enum.KeyCode.Eight] = "8",
		[Enum.KeyCode.Nine] = "9",
	}
	local function keyLabel(keyCode)
		if not keyCode then
			return "?"
		end
		return KEY_LABELS[keyCode] or tostring(keyCode.Name)
	end
	local floating
	local floatingCorner
	local tabs = {}
	local scrollFrames = {}
	local activeTab = nil
	local closeDropdown = nil
	local updateScale
	local updateHUD
	local showConfirm
	local showNotification

	function setWindowVisible(visible)
		window.Visible = visible
		if floating then
			floating.Visible = (not visible) and interfaceState.floatingButton
		end
	end

	local function applyIconStyle()
		local opacity = math.clamp(interfaceState.iconOpacity or 1, 0, 1)
		local scale = math.clamp(interfaceState.iconSize or 1, 0.5, 1.5)
		if not floating then
			return
		end

		local floatSize = math.max(28, math.floor(56 * scale + 0.5))
		floating.Size = UDim2.fromOffset(floatSize, floatSize)
		floating.TextSize = math.max(12, math.floor(20 * scale + 0.5))
		floating.BackgroundTransparency = 1 - opacity
		floating.TextTransparency = 1 - opacity
		floatingCorner.CornerRadius = UDim.new(0, math.max(6, math.floor(12 * scale + 0.5)))
	end

	local function applyGuiStyle()
		local opacity = math.clamp(interfaceState.guiOpacity or 1, 0, 1)
		window.BackgroundTransparency = 1 - opacity
		if sidebar then
			sidebar.BackgroundTransparency = 1 - opacity
		end
		if statusBar then
			statusBar.BackgroundTransparency = 1 - opacity
		end
	end

	-- Keep gameplay camera mouse-look working: the cursor is released only while
	-- the menu is open. When the menu closes the mouse is locked back to the game
	-- so the camera turns with mouse movement instead of requiring right-click.
	local originalMouseState = {
		behavior = UserInputService.MouseBehavior,
		icon = UserInputService.MouseIconEnabled,
	}

	local function applyMouseBehavior(menuOpen)
		if isMobile then
			return
		end
		local unlocked = menuOpen == true
		pcall(function()
			UserInputService.MouseBehavior = unlocked and Enum.MouseBehavior.Default or Enum.MouseBehavior.LockCenter
		end)
		pcall(function()
			-- Keep the cursor visible so it does not seem to vanish when the menu
			-- closes. Camera mouse-look still works because the pointer is locked.
			UserInputService.MouseIconEnabled = true
		end)
	end

