	local function addToggle(parent, key, label, description, options)
		options = options or {}
		local row = make("TextButton", {
			Name = "Toggle_" .. key,
			Size = UDim2.new(1, 0, 0, description and 52 or 44),
			BackgroundColor3 = theme.Card,
			AutoButtonColor = false,
			Text = "",
			BorderSizePixel = 0,
			LayoutOrder = #parent:GetChildren(),
		}, parent)
		addCorner(row, 10)
		local rowStroke = addStroke(row, theme.Stroke, 1, 0.25)

		make("TextLabel", {
			Text = label,
			Font = fonts.Medium,
			TextSize = 13,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, description and 8 or 13),
			Size = UDim2.new(1, -86, 0, 16),
		}, row)

		if description then
			make("TextLabel", {
				Text = description,
				Font = fonts.Regular,
				TextSize = 10,
				TextColor3 = theme.SubText,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextWrapped = true,
				BackgroundTransparency = 1,
				Position = UDim2.fromOffset(14, 26),
				Size = UDim2.new(1, -90, 0, 18),
			}, row)
		end

		local track = make("TextButton", {
			Name = "Switch",
			Text = "",
			AutoButtonColor = false,
			Size = UDim2.fromOffset(48, 26),
			Position = UDim2.new(1, -60, 0, description and 13 or 9),
			BackgroundColor3 = theme.Stroke,
			BorderSizePixel = 0,
			ZIndex = 5,
		}, row)
		addCorner(track, 13)

		local knob = make("Frame", {
			Name = "Knob",
			Size = UDim2.fromOffset(20, 20),
			Position = UDim2.fromOffset(3, 3),
			BackgroundColor3 = theme.Text,
			BorderSizePixel = 0,
			ZIndex = 6,
		}, track)
		addCorner(knob, 10)

		local function setValue(value)
			value = value == true
			tween(track, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				BackgroundColor3 = value and theme.Accent or theme.Stroke,
			})
			tween(knob, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Position = value and UDim2.fromOffset(25, 3) or UDim2.fromOffset(3, 3),
				BackgroundColor3 = value and Color3.fromRGB(12, 12, 14) or theme.Text,
			})
			rowStroke.Transparency = value and 0 or 0.25
			rowStroke.Color = value and theme.Accent or theme.Stroke
		end

		setValue(Effects.state.toggles[key])
		if toggles[key] then
			warn("[ShaderVelard] duplicate toggle widget for key '" .. tostring(key) .. "'")
		end
		toggles[key] = { setValue = setValue }

		local lastToggle = 0
		local function applyValue(nextValue)
			setValue(nextValue)
			local ok, err = pcall(function()
				Effects.setToggle(key, nextValue)
			end)
			if not ok then
				warn("[ShaderVelard] toggle '" .. key .. "' failed: " .. tostring(err))
			end
			setValue(Effects.state.toggles[key])
		end

		local function toggle()
			local now = os.clock()
			if now - lastToggle < 0.05 then
				return
			end
			lastToggle = now
			local nextValue = not (Effects.state.toggles[key] == true)

			if Effects.isToggleLocked and Effects.isToggleLocked(key) then
				setValue(true)
				if not nextValue then
					showNotification(
						"Locked for this session",
						options.lockedMessage or "This feature is permanently enabled until you rejoin the game.",
						5
					)
				end
				return
			end

			if nextValue and options.confirm then
				-- Irreversible actions ask first. The switch only flips after the
				-- player explicitly agrees, and then the feature is locked on.
				showConfirm(options.confirm, function()
					if Effects.lockToggle then
						Effects.lockToggle(key)
					end
					applyValue(true)
					if options.successMessage then
						showNotification("Locked for this session", options.successMessage, 5)
					end
				end)
				return
			end

			applyValue(nextValue)
		end

		row.MouseEnter:Connect(function()
			row.BackgroundColor3 = theme.CardHover
		end)
		row.MouseLeave:Connect(function()
			row.BackgroundColor3 = theme.Card
		end)
		row.Activated:Connect(toggle)
		track.Activated:Connect(toggle)

		return row
	end

