		end)
		row.Activated:Connect(toggle)
		track.Activated:Connect(toggle)

		return { setValue = setValue, row = row }
	end

	local function formatValue(value, step)
		if step >= 1 then
			return tostring(math.round(value))
		end
		return string.format("%.2f", value)
	end

	local function addSlider(parent, key, label, minimum, maximum, step, suffix, onChange, initialValue)
		local row = make("Frame", {
			Name = "Slider_" .. key,
			Size = UDim2.new(1, 0, 0, 56),
			BackgroundColor3 = theme.Card,
			BorderSizePixel = 0,
			LayoutOrder = #parent:GetChildren(),
		}, parent)
		addCorner(row, 10)
		addStroke(row, theme.Stroke, 1, 0.3)

		make("TextLabel", {
			Text = label,
			Font = fonts.Medium,
			TextSize = 12,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(12, 7),
			Size = UDim2.new(0.7, 0, 0, 16),
		}, row)

		local valueLabel = make("TextLabel", {
			Text = "",
			Font = fonts.Mono,
			TextSize = 11,
			TextColor3 = theme.Accent,
			TextXAlignment = Enum.TextXAlignment.Right,
			BackgroundTransparency = 1,
			Position = UDim2.new(1, -90, 0, 7),
			Size = UDim2.fromOffset(78, 16),
		}, row)

		local track = make("Frame", {
			Name = "Track",
			Size = UDim2.new(1, -24, 0, 5),
			Position = UDim2.fromOffset(12, 38),
			BackgroundColor3 = theme.Stroke,
			BorderSizePixel = 0,
			Active = true,
		}, row)
		addCorner(track, 3)

		local fill = make("Frame", {
			Name = "Fill",
			Size = UDim2.new(0, 0, 1, 0),
			BackgroundColor3 = theme.Accent,
			BorderSizePixel = 0,
		}, track)
		addCorner(fill, 3)
		addGradient(fill, ColorSequence.new(theme.Accent, theme.Accent2), 0)

		local knob = make("Frame", {
			Name = "Knob",
			Size = UDim2.fromOffset(13, 13),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0, 0, 0.5, 0),
			BackgroundColor3 = theme.Text,
			BorderSizePixel = 0,
			ZIndex = 5,
			Active = true,
		}, track)
		addCorner(knob, 7)
		addStroke(knob, theme.Accent, 2, 0)

		local suffixText = suffix or ""
		local currentValue = initialValue
		if currentValue == nil then
			currentValue = Effects.state.sliders[key]
		end
		if currentValue == nil then
			currentValue = minimum
		end

		local function setValue(value, invoke)
			currentValue = math.clamp(value, minimum, maximum)
			currentValue = math.round(currentValue / step) * step
			local alpha = (currentValue - minimum) / math.max(maximum - minimum, 0.0001)
			fill.Size = UDim2.new(alpha, 0, 1, 0)
			knob.Position = UDim2.new(alpha, 0, 0.5, 0)
			valueLabel.Text = formatValue(currentValue, step) .. suffixText
			if invoke then
				if onChange then
					onChange(currentValue)
				else
					Effects.setSlider(key, currentValue)
				end
			end
		end

		setValue(currentValue, false)
		if not onChange then
			if sliders[key] then
				warn("[ShaderVelard] duplicate slider widget for key '" .. tostring(key) .. "'")
			end
			sliders[key] = { setValue = setValue }
		end

		local dragging = false
		local function setFromX(x)
			local width = math.max(track.AbsoluteSize.X, 1)
			local alpha = math.clamp((x - track.AbsolutePosition.X) / width, 0, 1)
			local value = minimum + (maximum - minimum) * alpha
			setValue(value, true)
		end

		local function beginDrag(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				setFromX(input.Position.X)
			end
		end

		track.InputBegan:Connect(beginDrag)
		knob.InputBegan:Connect(beginDrag)

		UserInputService.InputChanged:Connect(function(input)
			if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement
				or input.UserInputType == Enum.UserInputType.Touch) then
				setFromX(input.Position.X)
			end
		end)

		UserInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch then
				dragging = false
			end
		end)

		return row
	end

	local function closePopup()
		if closeDropdown then
			closeDropdown()
			closeDropdown = nil
		end
	end

	local function addDropdown(parent, key, label, options, current, callback)
		local optionSource = options
		local rowHeight = isMobile and 66 or 48
		local row = make("Frame", {
			Name = "Dropdown_" .. key,
			Size = UDim2.new(1, 0, 0, rowHeight),
			BackgroundColor3 = theme.Card,
			BorderSizePixel = 0,
			LayoutOrder = #parent:GetChildren(),
		}, parent)
		addCorner(row, 10)
		addStroke(row, theme.Stroke, 1, 0.3)

		make("TextLabel", {
			Text = label,
			Font = fonts.Medium,
			TextSize = 12,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = isMobile and UDim2.fromOffset(12, 9) or UDim2.fromOffset(12, 16),
			Size = isMobile and UDim2.new(1, -24, 0, 16) or UDim2.new(0.5, 0, 0, 16),
		}, row)

		local button = make("TextButton", {
			Name = "Button",
			Text = current .. "  v",
			Font = fonts.Medium,
			TextSize = 11,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundColor3 = theme.BgSoft,
			AutoButtonColor = false,
			Position = isMobile and UDim2.fromOffset(12, 29) or UDim2.new(1, -190, 0, 9),
			Size = isMobile and UDim2.new(1, -24, 0, 30) or UDim2.fromOffset(178, 30),
			BorderSizePixel = 0,
		}, row)
		addCorner(button, 8)
		addStroke(button, theme.Stroke, 1, 0.1)
		local buttonPadding = Instance.new("UIPadding")
		buttonPadding.PaddingLeft = UDim.new(0, 10)
		buttonPadding.Parent = button

		local setValue = function(value)
			current = value
			button.Text = value .. "  v"
		end

		button.Activated:Connect(function()
			closePopup()
			if type(optionSource) == "function" then
				options = optionSource() or {}
			else
				options = optionSource or {}
			end
			if #options == 0 then
				options = { "None" }
			end

			local backdrop = make("TextButton", {
				Name = "DropdownBackdrop",
				Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1,
				Text = "",
				AutoButtonColor = false,
				ZIndex = 490,
			}, gui)

			local popupHeight = math.min(#options * 27 + 10, 250)
			local camera = workspace.CurrentCamera
			local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
			local popupWidth = isMobile and math.max(button.AbsoluteSize.X, 160) or 210
			local popupX = math.clamp(button.AbsolutePosition.X, 4, math.max(viewport.X - popupWidth - 4, 4))
			local popupY = button.AbsolutePosition.Y + button.AbsoluteSize.Y + 4
			if popupY + popupHeight > viewport.Y - 4 then
				popupY = math.max(button.AbsolutePosition.Y - popupHeight - 4, 4)
			end
			local popup = make("Frame", {
				Name = "DropdownPopup",
				Size = UDim2.fromOffset(popupWidth, popupHeight),
				Position = UDim2.fromOffset(popupX, popupY),
				BackgroundColor3 = theme.BgSoft,
				BorderSizePixel = 0,
				ZIndex = 500,
			}, gui)
			addCorner(popup, 10)
			addStroke(popup, theme.Accent, 1, 0.4)

			local list = make("ScrollingFrame", {
				Name = "Options",
				Size = UDim2.new(1, -8, 1, -8),
				Position = UDim2.fromOffset(4, 4),
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				ScrollBarThickness = 3,
				ScrollBarImageColor3 = theme.Muted,
				CanvasSize = UDim2.new(),
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				ZIndex = 501,
			}, popup)
			local layout = Instance.new("UIListLayout")
			layout.Padding = UDim.new(0, 2)
			layout.SortOrder = Enum.SortOrder.LayoutOrder
			layout.Parent = list

			for index, option in ipairs(options) do
				local optionButton = make("TextButton", {
					Name = "Option" .. index,
					Text = option,
					Font = fonts.Medium,
					TextSize = 11,
					TextColor3 = option == current and theme.Accent or theme.Text,
					TextXAlignment = Enum.TextXAlignment.Left,
					BackgroundColor3 = option == current and theme.CardHover or theme.BgSoft,
					AutoButtonColor = false,
					Size = UDim2.new(1, 0, 0, 25),
					BorderSizePixel = 0,
					LayoutOrder = index,
					ZIndex = 501,
				}, list)
				addCorner(optionButton, 6)
				local padding = Instance.new("UIPadding")
				padding.PaddingLeft = UDim.new(0, 8)
				padding.Parent = optionButton
				optionButton.Activated:Connect(function()
					setValue(option)
					closePopup()
					callback(option)
				end)
			end

			closeDropdown = function()
				if backdrop and backdrop.Parent then
					backdrop:Destroy()
				end
				if popup and popup.Parent then
					popup:Destroy()
				end
			end
			backdrop.Activated:Connect(closePopup)
		end)

		if dropdowns[key] then
			warn("[ShaderVelard] duplicate dropdown widget for key '" .. tostring(key) .. "'")
		end
		dropdowns[key] = { setValue = setValue }
		return row
	end

