	local function addButton(parent, label, accent, callback, height)
		local button = make("TextButton", {
			Name = "Button_" .. label,
			Text = label,
			Font = fonts.Bold,
			TextSize = 12,
			TextColor3 = accent and Color3.fromRGB(12, 12, 14) or theme.Text,
