		end)
		agree.MouseLeave:Connect(function()
			agree.BackgroundColor3 = Color3.fromRGB(196, 58, 58)
		end)

		local closed = false
		local function close()
			if closed then
				return
			end
			closed = true
			if activeConfirm == overlay then
				activeConfirm = nil
			end
			if overlay.Parent then
				overlay:Destroy()
			end
		end

		-- GuiObject.Activated can be swallowed by the Active confirm overlay,
		-- especially on touch, so bind the buttons to raw press/release input.
		local function bindPress(button, callback)
			local armed = false
			button.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch then
					armed = true
				end
			end)
			button.InputEnded:Connect(function(input)
				if not armed then
					return
				end
				if input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch then
					armed = false
					callback()
				end
			end)
		end

		local confirmed = false
		bindPress(cancel, close)
		bindPress(agree, function()
			if confirmed then
				return
			end
			confirmed = true
			close()
			if type(onConfirm) == "function" then
				task.defer(onConfirm)
			end
		end)

		card.Size = UDim2.fromOffset(cardWidth, 290)
		tween(card, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			Size = UDim2.fromOffset(cardWidth, 304),
		})
		return overlay
	end

	local function createTab(name, label, order)
		local button = make("TextButton", {
			Name = "Tab_" .. name,
			Text = label,
			Font = fonts.Bold,
			TextSize = 11,
			TextColor3 = theme.SubText,
			TextXAlignment = isMobile and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left,
			BackgroundColor3 = theme.BgSoft,
			AutoButtonColor = false,
			Size = isMobile and UDim2.fromOffset(0, 30) or UDim2.new(1, 0, 0, 34),
			AutomaticSize = isMobile and Enum.AutomaticSize.X or Enum.AutomaticSize.None,
			BorderSizePixel = 0,
			LayoutOrder = order,
			ZIndex = 4,
		}, tabList)
		addCorner(button, 8)
		local padding = Instance.new("UIPadding")
		padding.PaddingLeft = UDim.new(0, 12)
		padding.PaddingRight = UDim.new(0, isMobile and 12 or 0)
		padding.Parent = button

		local marker
		if isMobile then
			marker = make("Frame", {
				Name = "Marker",
				Size = UDim2.new(1, 0, 0, 2),
				Position = UDim2.new(0, 0, 1, -2),
				BackgroundColor3 = theme.Accent,
				BorderSizePixel = 0,
				Visible = false,
				ZIndex = 5,
			}, button)
		else
			marker = make("Frame", {
				Name = "Marker",
				Size = UDim2.new(0, 3, 0, 16),
				Position = UDim2.fromOffset(0, 9),
				BackgroundColor3 = theme.Accent,
				BorderSizePixel = 0,
				Visible = false,
				ZIndex = 5,
			}, button)
			addCorner(marker, 2)
		end

		local scroll = make("ScrollingFrame", {
			Name = "Scroll_" .. name,
			Size = UDim2.new(1, -(EDGE * 2), 1, -(EDGE * 2)),
			Position = UDim2.fromOffset(EDGE, EDGE),
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ScrollBarThickness = 4,
			ScrollBarImageColor3 = theme.Muted,
			ScrollBarImageTransparency = 0.3,
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			Visible = false,
			ZIndex = 3,
		}, contentArea)
		local layout = Instance.new("UIListLayout")
		layout.Padding = UDim.new(0, 7)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = scroll
		local scrollPadding = Instance.new("UIPadding")
		scrollPadding.PaddingRight = UDim.new(0, 6)
		scrollPadding.PaddingBottom = UDim.new(0, 8)
		scrollPadding.Parent = scroll

		tabs[name] = { button = button, marker = marker, scroll = scroll, label = label }
		scrollFrames[name] = scroll

		button.Activated:Connect(function()
			selectTab(name)
		end)

		return scroll
	end

	function selectTab(name)
		closePopup()
		for tabName, tab in pairs(tabs) do
			local selected = tabName == name
			tab.scroll.Visible = selected
			tab.marker.Visible = selected
			tab.button.TextColor3 = selected and theme.Accent or theme.SubText
			tab.button.BackgroundColor3 = selected and theme.Card or theme.BgSoft
			if selected then
				activeTab = tabName
			end
		end
	end

