	-- Hotkey helpers for cycling presets and skyboxes.
	local function cyclePreset(step)
		local names = Effects.getPresetNames()
		if #names == 0 then
			return
		end
		local currentIndex = 0
		for index, name in ipairs(names) do
			if name == Effects.state.presetName then
				currentIndex = index
				break
			end
		end
		for offset = 1, #names do
			local index = ((currentIndex - 1 + step * offset) % #names) + 1
			local name = names[index]
			Effects.applyPreset(name)
			showNotification("Preset Hotkey", name, 4)
			return
		end
	end

	local function cycleSky(step)
		local names = Effects.getSkyNames()
		if #names == 0 then
			return
		end
		local currentIndex = tonumber(Effects.state.skyIndex) or 1
		local index = ((currentIndex - 1 + step) % #names) + 1
		local name = names[index]
		Effects.applySky(name)
		showNotification("Skybox Hotkey", name, 4)
	end

