	local presetCardEntries = {}

	local function addPresetCard(parent, preset)
		local card = make("TextButton", {
			Name = "Preset_" .. preset.Name,
			Text = "",
			BackgroundColor3 = theme.Card,
			AutoButtonColor = false,
			Size = UDim2.new(1, 0, 0, 58),
			BorderSizePixel = 0,
			LayoutOrder = #parent:GetChildren(),
		}, parent)
		addCorner(card, 10)
		local cardStroke = addStroke(card, theme.Stroke, 1, 0.3)
		local accent = make("Frame", {
			Name = "Accent",
			Size = UDim2.new(0, 3, 0, 34),
			Position = UDim2.fromOffset(0, 12),
			BackgroundColor3 = preset.AccentColor or theme.Stroke,
			BorderSizePixel = 0,
		}, card)
		addCorner(accent, 2)

		make("TextLabel", {
			Text = preset.Name,
			Font = fonts.Bold,
			TextSize = 12,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, 7),
			Size = UDim2.new(1, -90, 0, 16),
		}, card)
		local badge = make("TextLabel", {
			Name = "Tier",
			Text = "",
			Font = fonts.Bold,
			TextSize = 8,
			TextColor3 = theme.Muted,
			TextXAlignment = Enum.TextXAlignment.Right,
			BackgroundTransparency = 1,
			Position = UDim2.new(1, -78, 0, 9),
			Size = UDim2.fromOffset(64, 12),
			Visible = false,
		}, card)
		make("TextLabel", {
			Text = preset.Desc,
			Font = fonts.Regular,
			TextSize = 10,
			TextColor3 = theme.SubText,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, 25),
			Size = UDim2.new(1, -28, 0, 28),
		}, card)

		card.MouseEnter:Connect(function()
			card.BackgroundColor3 = theme.CardHover
		end)
		card.MouseLeave:Connect(function()
			card.BackgroundColor3 = theme.Card
		end)
		card.Activated:Connect(function()
			applyPresetWithGate(preset.Name)
		end)

		presetCards[preset.Name] = { card = card, stroke = cardStroke, accent = accent, accentColor = preset.AccentColor }
		presetCardEntries[#presetCardEntries + 1] = {
			name = preset.Name,
			card = card,
			stroke = cardStroke,
			accent = accent,
			accentColor = preset.AccentColor,
			badge = badge,
		}
		return card
	end

