	addSection(presetsTab, "Custom Presets")
	infoLabel(presetsTab, "Save the complete current look under a name, then apply or delete it later. Files are stored by your executor as ShaderVelard_Presets.txt.", 30)
	local _, customNameBox = addTextBox(presetsTab, "Preset Name", "Enter the name for your custom preset", "", function() end)

	local customList = make("Frame", {
		Name = "CustomPresetList",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		LayoutOrder = #presetsTab:GetChildren(),
	}, presetsTab)
	local customLayout = Instance.new("UIListLayout")
	customLayout.Padding = UDim.new(0, 6)
	customLayout.SortOrder = Enum.SortOrder.LayoutOrder
	customLayout.Parent = customList

	local function refreshCustomPresets()
		for _, child in ipairs(customList:GetChildren()) do
			if child:IsA("GuiObject") then
				child:Destroy()
			end
		end
		local names = Effects.getCustomPresetNames()
		if #names == 0 then
			make("TextLabel", {
				Text = "No Presets Found",
				Font = fonts.Regular,
				TextSize = 11,
				TextColor3 = theme.Muted,
				TextXAlignment = Enum.TextXAlignment.Left,
				BackgroundColor3 = theme.Card,
				Size = UDim2.new(1, 0, 0, 30),
				LayoutOrder = 1,
			}, customList)
			return
		end
		for index, name in ipairs(names) do
			local row = make("Frame", {
				Name = "CustomPreset_" .. index,
				Size = UDim2.new(1, 0, 0, 34),
				BackgroundColor3 = theme.Card,
				BorderSizePixel = 0,
				LayoutOrder = index,
			}, customList)
			addCorner(row, 8)
			addStroke(row, theme.Stroke, 1, 0.3)
			local applyButton = make("TextButton", {
				Text = name,
				Font = fonts.Medium,
				TextSize = 11,
				TextColor3 = theme.Text,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				BackgroundTransparency = 1,
				AutoButtonColor = false,
				Position = UDim2.fromOffset(10, 0),
				Size = UDim2.new(1, -80, 1, 0),
			}, row)
			local deleteButton = make("TextButton", {
				Text = "Delete",
				Font = fonts.Medium,
				TextSize = 10,
				TextColor3 = theme.Danger,
				BackgroundColor3 = theme.BgSoft,
				AutoButtonColor = false,
				Position = UDim2.new(1, -66, 0, 4),
				Size = UDim2.fromOffset(58, 26),
			}, row)
			addCorner(deleteButton, 6)
			applyButton.Activated:Connect(function()
				local ok, err = Effects.applyCustomPreset(name)
				if ok then
					showNotification("Preset Applied", name, 6)
				else
					showNotification("Failed to load preset", tostring(err), 6)
				end
			end)
			deleteButton.Activated:Connect(function()
				local ok, err = Effects.deleteCustomPreset(name)
				if ok then
					refreshCustomPresets()
					showNotification("Preset Deleted", name .. " deleted.", 6)
				else
					showNotification("Failed to delete presets", tostring(err), 6)
				end
			end)
		end
	end

	addButton(presetsTab, "Save Preset", true, function()
		local ok, message = Effects.saveCustomPreset(customNameBox.Text)
		if ok then
			refreshCustomPresets()
			showNotification("Preset Saved", tostring(message), 6)
		else
			showNotification("Save Failed", tostring(message), 6)
		end
	end)
	addButton(presetsTab, "Refresh Preset List", false, function()
		Effects.refreshCustomPresets()
		refreshCustomPresets()
		showNotification("Preset List", "Preset list refreshed.", 5)
	end)
	addButton(presetsTab, "Delete All Presets", false, function()
		local ok, message = Effects.deleteAllCustomPresets()
		refreshCustomPresets()
		showNotification(ok and "Presets Deleted" or "Delete Failed", tostring(message), 6)
	end)
	refreshCustomPresets()

