	local customSkyBoxes = {}
	local customSkyFaceDefs = {
		{ key = "Bk", label = "Back (Bk)" },
		{ key = "Dn", label = "Down (Dn)" },
		{ key = "Ft", label = "Front (Ft)" },
		{ key = "Lf", label = "Left (Lt)" },
