		{ key = "Up", label = "Up (Up)" },
	}
	addSection(skyTab, "Skybox")
	infoLabel(skyTab, "Skybox textures stream from Roblox assets. Some IDs may take a moment to load.", 28)
	addDropdown(skyTab, "sky", "Active Skybox", Effects.getSkyNames(), Effects.state.skyName, function(value)
		Effects.applySky(value)
	end)

	addSection(skyTab, "Custom 6-Face Skybox")
	infoLabel(skyTab, "Paste six Roblox texture IDs. Numeric IDs and rbxassetid:// links are accepted.", 28)
	for _, face in ipairs(customSkyFaceDefs) do
		local _, box = addTextBox(skyTab, face.label, "rbxassetid://...", Effects.state.customSky[face.key], function() end)
		customSkyBoxes[face.key] = box
	end
	addButton(skyTab, "Apply Custom Skybox", true, function()
		local faces = {}
		for _, face in ipairs(customSkyFaceDefs) do
			local box = customSkyBoxes[face.key]
			faces[face.key] = box and box.Text or ""
		end
		local result, reason = Effects.applyCustomSky(faces)
		if result then
			for _, face in ipairs(customSkyFaceDefs) do
				customSkyBoxes[face.key].Text = Effects.state.customSky[face.key]
			end
			showNotification("Custom Skybox", "Applied all six sky faces.")
		else
			showNotification("Skybox Error", tostring(reason or "Invalid texture ID."))
		end
	end)
	addButton(skyTab, "Revert to Game Original Skybox", false, function()
		Effects.revertSkybox()
		showNotification("Skybox", "Restored the game's original skybox.")
	end)

	addSection(skyTab, "Skybox Scanner / Generator")
	addButton(skyTab, "Scan Current Skybox", false, function()
		local sky = LightingService:FindFirstChildOfClass("Sky")
		if not sky then
			showNotification("Skybox Scanner", "No Sky object found in Lighting.", 5)
			return
		end
		local copied = 0
		for _, face in ipairs(customSkyFaceDefs) do
			local value = sky[face.key]
			if value and value ~= "" then
				customSkyBoxes[face.key].Text = value
				copied = copied + 1
			end
		end
		showNotification("Skybox Scanned", tostring(copied) .. " sky faces copied into the custom boxes.", 5)
	end)
	addButton(skyTab, "Generate Random Skybox", false, function()
		local sky = Config.Skyboxes[math.random(1, #Config.Skyboxes)]
		Effects.applySky(sky.Name)
		showNotification("Skybox Generator", "Rolled " .. sky.Name, 5)
	end)

