	local _, uniformSkyBox = addTextBox(advanceTab, "Uniform Sky ID", "rbxassetid://123456789", "", function() end)
	addButton(advanceTab, "Apply Uniform ID to All 6 Faces", true, function()
		local code = tostring(uniformSkyBox.Text or ""):gsub("%s", "")
		if code == "" then
			showNotification("Skybox", "Enter a texture ID first.", 5)
			return
		end
		if tonumber(code) then
			code = "rbxassetid://" .. code
		end
		local faces = { Bk = code, Dn = code, Ft = code, Lf = code, Rt = code, Up = code }
		local ok, reason = Effects.applyCustomSky(faces, "Uniform Sky")
		if ok then
			for _, face in ipairs(customSkyFaceDefs) do
				customSkyBoxes[face.key].Text = code
			end
			showNotification("Skybox", "Uniform texture applied to all faces.", 5)
		else
			showNotification("Skybox Error", tostring(reason), 5)
		end
	end)

